(173, 'bottpl', 'akhir', '{\"text\":\"Terima kasih sudah ngobrol dengan {nama_klinik}, {nama}! 😊\\nKalau ada pertanyaan lagi, chat kami kapan saja ya.\\n\\n{promo_aktif}\\nYuk jaga senyum dengan kontrol rutin 6 bulan sekali 🦷✨\"}'),
(163, 'bottpl', 'asuransi', '{\"text\":\"Daftar asuransi yang bekerja sama dengan kami:\\n{daftar_asuransi}\\n\\nMohon konfirmasi masa berlaku dan cakupan polis ke bagian pendaftaran.\"}'),
(172, 'bottpl', 'auto_balas', '{\"text\":\"Halo {nama}! Terima kasih sudah menghubungi kami 😊 Pesan Anda sudah kami terima dan akan dibalas pada jam layanan ({jam_kerja}).\"}'),
(165, 'bottpl', 'biaya', '{\"text\":\"Biaya perawatan bergantung pada hasil pemeriksaan dokter. Untuk perkiraan biaya, silakan hubungi bagian pendaftaran.\"}'),
(168, 'bottpl', 'hubungkan', '{\"text\":\"Baik, saya hubungkan ke bagian pendaftaran😉. Mohon isi nama dan nomor telepon Anda supaya petugas bisa menghubungi kembali bila chat terputus.\"}'),
(159, 'bottpl', 'jadwal', '{\"text\":\"Berikut jadwal praktek dokter:\\n{daftar_jadwal}\\n\\nMohon konfirmasi ketersediaan ke bagian pendaftaran sebelum kunjungan.\"}'),
(161, 'bottpl', 'jadwal_hari_ini', '{\"text\":\"Jadwal praktek hari ini ({hari}) 🗓️\\n{daftar_jadwal}\\n\\nMau dibantu daftar? Pilih \\\"Hubungi pendaftaran\\\" ya.\"}'),
(160, 'bottpl', 'jadwal_kosong', '{\"text\":\"Maaf, jadwal yang Anda cari belum tercatat nih. Boleh langsung tanya ke pendaftaran ya, mereka siap bantu 🙏\"}'),
(164, 'bottpl', 'janji', '{\"text\":\"Janji temu dapat dibuat melalui formulir di halaman Contact atau melalui bagian pendaftaran.\"}'),
(167, 'bottpl', 'keluhan', '{\"text\":\"Mohon maaf atas ketidaknyamanan Anda. Kami tidak dapat mendiagnosis melalui chat.\\nBila keluhan berat (pembengkakan menyebar, pendarahan tidak berhenti, sulit menelan atau bernapas), segera ke IGD terdekat.\\nUntuk konsultasi, silakan hubungi bagian pendaftaran.\"}'),
(162, 'bottpl', 'layanan', '{\"text\":\"Layanan dan spesialisasi kami📝:\\n{daftar_layanan}\\n\\nUntuk rincian tindakan dan biaya, silahkan hubungi bagian pendaftaran.\"}'),
(170, 'bottpl', 'menunggu', '{\"text\":\"Pesan Anda sudah masuk ya 😊 Petugas pendaftaran akan segera membalas (jam layanan: {jam_kerja}). Mohon ditunggu sebentar.\"}'),
(166, 'bottpl', 'promo', '{\"text\":\"Promo yang sedang berlaku:\\n{daftar_promo}\\n\\nUntuk informasi dan pemesanan, silakan hubungi bagian pendaftaran.\"}'),
(158, 'bottpl', 'sapaan', '{\"text\":\"Halo, selamat datang di {nama_klinik}! 😊🦷\\nSaya asisten virtual yang siap bantu info jadwal dokter, layanan, asuransi, promo, dan jam buka. Kalau butuh bantuan langsung, tinggal pilih \\\"Hubungi pendaftaran\\\" ya.\"}'),
(171, 'bottpl', 'terhubung', '{\"text\":\"Terhubung ke pendaftaran. Halo {nama}, silakan tulis kebutuhan Anda ya 😊\"}'),
(169, 'bottpl', 'tidak_paham', '{\"text\":\"Maaf, saya belum paham maksudnya 😅 Coba pilih salah satu topik di bawah, atau langsung ngobrol dengan pendaftaran ya.\"}'),
(376, 'cases', 'mwbj1079', '{\"title\":\"Perawatan Saluran Akar pada Gigi Berlubang Dalam\",\"dept\":\"Konservasi Gigi / Endodontic\",\"doctor\":\"Dr. drg. Anggraeni, Sp.KG\",\"year\":\"\",\"problem\":\"Gigi geraham berlubang dalam dan terasa nyeri saat mengunyah.\",\"tools\":\"Dental Unit\\nApex Locator\\nRotary Endodontic\",\"desc\":\"Perawatan saluran akar dilakukan untuk membersihkan jaringan pulpa yang terinfeksi. Gigi kemudian direstorasi untuk membantu mengembalikan fungsi pengunyahan.\",\"img\":\"/uploads/3a7bb856fc9ef0e955a9869eb42c65a5.png\",\"imgpos\":\"50% 0%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(377, 'cases', 'mwbjw03b', '{\"title\":\"Restorasi Estetik Gigi Depan yang Patah\",\"dept\":\"Konservasi Gigi / Endodontic\",\"doctor\":\"Drg. Dewi Isroyati Sugiana, Sp. KG\",\"year\":\"\",\"problem\":\"Gigi depan patah sebagian dan mengganggu penampilan senyum.\",\"tools\":\"Dental Unit\\nShade Guide\\nLight Curing Unit\",\"desc\":\"Restorasi menggunakan resin komposit dilakukan untuk memperbaiki bentuk dan estetika gigi depan.\",\"img\":\"/uploads/7ae2d655ce8b1a6d2aaf5f7fe2bb0424.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(378, 'cases', 'mwbjykth', '{\"title\":\"Perawatan Behel Metal pada Gigi Berjejal\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"doctor\":\"Drg. Benazir Amriza Dini, Sp. Ortho\",\"year\":\"\",\"problem\":\"Susunan gigi tidak rata dan sulit dibersihkan.\",\"tools\":\"Bracket Metal\\nArchwire\\nOrthodontic Pliers\",\"desc\":\"Perawatan ortodonti dilakukan untuk memperbaiki susunan gigi melalui kontrol berkala.\",\"img\":\"/uploads/7c0ec222886e79a260730e6c38ee9cf0.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"/uploads/6fd255c2acc943108c0b5c2bd87fbdca.jpg\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(379, 'cases', 'mwbkbcdm', '{\"title\":\"Perawatan Aligner untuk Merapikan Gigi\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"doctor\":\"Drg. Irma Aryani, Sp. Ort\",\"year\":\"\",\"problem\":\"Gigi depan renggang dan kurang rapi.\",\"tools\":\"Clear Aligner\\nIntraoral Scanner\\nSoftware Perencanaan Aligner\",\"desc\":\"Perawatan menggunakan aligner transparan direncanakan untuk membantu memperbaiki posisi gigi secara bertahap.\",\"img\":\"/uploads/d86c6ae8b33bcc917b9f6f189b5dffac.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(380, 'cases', 'mwbkedqk', '{\"title\":\"Pencabutan Gigi Bungsu Impaksi\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"doctor\":\"Drg. Isma Tria Savitri, Sp. BM\",\"year\":\"\",\"problem\":\"Nyeri dan pembengkakan di area gigi bungsu.\",\"tools\":\"Dental Unit\\nInstrumen Bedah Mulut\\nRontgen Panoramik\",\"desc\":\"Evaluasi dan tindakan pencabutan gigi bungsu dilakukan sesuai kondisi klinis.\",\"img\":\"/uploads/aed65108b773ea29f59164bb4bc9d7c6.jpg\",\"imgpos\":\"81% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(381, 'cases', 'mwbkhttu', '{\"title\":\"Frenectomy (Perbaikan Frenulum Lidah)\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"doctor\":\"Drg. Teuku Ahmad Arbi, Sp.BMM, Subsp.IDM(K)\",\"year\":\"\",\"problem\":\"Gerakan lidah terbatas sehingga mengganggu fungsi tertentu.\",\"tools\":\"Dental Unit\\nElectrosurgery\\nSurgical Instrument Set\",\"desc\":\"Frenectomy dilakukan berdasarkan indikasi klinis untuk membantu meningkatkan mobilitas jaringan.\",\"img\":\"/uploads/756079cba60799d36d8aaacc2c8010a4.jpg\",\"imgpos\":\"50% 27%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(382, 'cases', 'mwbklai7', '{\"title\":\"Pemasangan Crown pada Gigi yang Rusak\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"doctor\":\"Drg. Brian Vensen Lika, Sp. Pros\",\"year\":\"\",\"problem\":\"Gigi geraham rusak dan fungsi pengunyahan terganggu.\",\"tools\":\"Dental Unit\\nScanner Intraoral\\nCrown Metal Porcelain\",\"desc\":\"Restorasi crown direncanakan untuk membantu mengembalikan bentuk dan fungsi gigi.\",\"img\":\"/uploads/0ae481695d0bdf93e35ab49f8892a1f0.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(383, 'cases', 'mwbknpmx', '{\"title\":\"Gigi Tiruan Lepasan Valplast\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"doctor\":\"Drg. Isya Hanin, Sp. Pros\",\"year\":\"\",\"problem\":\"Kehilangan beberapa gigi dan kesulitan mengunyah.\",\"tools\":\"Dental Unit\\nImpression Tray\\nValplast\",\"desc\":\"Pembuatan gigi tiruan lepasan dilakukan untuk membantu mengembalikan fungsi pengunyahan dan estetika.\",\"img\":\"/uploads/d80235ade8b7df950cd47163e1eda7b7.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(384, 'cases', 'mwbkpxbj', '{\"title\":\"Perawatan Radang Gusi (Gingivitis)\",\"dept\":\"Jaringan Penyangga Gigi / Periodontic\",\"doctor\":\"Drg. Riana Napitupulu, Sp.Perio\",\"year\":\"\",\"problem\":\"Gusi mudah berdarah dan terasa bengkak.\",\"tools\":\"Scaler Ultrasonic\\nCurette\\nPolishing Brush\",\"desc\":\"Scaling dan pembersihan karang gigi dilakukan untuk membantu mengurangi peradangan.\",\"img\":\"/uploads/597b581bc178423f20b7ce0802c6ce45.jpg\",\"imgpos\":\"45% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(385, 'cases', 'mwbksckv', '{\"title\":\"Perawatan Periodontitis dengan Root Planing\",\"dept\":\"Jaringan Penyangga Gigi / Periodontic\",\"doctor\":\"Drg. Fathia Agzarine Deandra, Sp. Perio\",\"year\":\"\",\"problem\":\"Gusi mengalami peradangan dan terdapat penumpukan karang gigi.\",\"tools\":\"Scaling & Root Planing\\nCurette\\nDental Unit\",\"desc\":\"Perawatan periodontal dilakukan untuk membersihkan permukaan akar gigi dan mendukung kesehatan jaringan gusi.\",\"img\":\"/uploads/201c69e04317d474301260bf05cbcf87.jpg\",\"imgpos\":\"50% 33%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(386, 'cases', 'mwbkvvbj', '{\"title\":\"Perawatan Karies pada Gigi Susu\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"doctor\":\"Drg. Annisa Rizki Amalia, Sp. KGA\",\"year\":\"\",\"problem\":\"Gigi susu berlubang dan terasa nyeri.\",\"tools\":\"Dental Unit\\nGlass Ionomer Cement\\nLight Curing Unit\",\"desc\":\"Perawatan karies dan restorasi gigi susu dilakukan sesuai kondisi gigi anak.\",\"img\":\"/uploads/ef70ca80b058fbf9b0563b2d77326485.jpg\",\"imgpos\":\"47% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(387, 'cases', 'mwbky4du', '{\"title\":\"Pit & Fissure Sealant untuk Pencegahan Karies\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"doctor\":\"Drg. Nidia Risky Primanda, Sp. KGA\",\"year\":\"\",\"problem\":\"Orang tua ingin membantu mencegah gigi geraham anak berlubang.\",\"tools\":\"Dental Unit\\nPit & Fissure Sealant\\nLight Curing Unit\",\"desc\":\"Sealant diaplikasikan pada permukaan gigi geraham untuk membantu melindungi area yang rentan terhadap karies.\",\"img\":\"/uploads/3f2ee4122ea10f290d56d20ffb42a051.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(388, 'cases', 'mwbkzziq', '{\"title\":\"Pembersihan Karang Gigi (Scaling)\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"doctor\":\"Drg. Arsy Muda\",\"year\":\"\",\"problem\":\"Gigi terasa kotor dan terdapat penumpukan karang gigi.\",\"tools\":\"Scaling dilakukan untuk membersihkan karang gigi dan membantu menjaga kebersihan rongga mulut.\",\"desc\":\"Scaling dilakukan untuk membersihkan karang gigi dan membantu menjaga kebersihan rongga mulut.\",\"img\":\"/uploads/12b6ead8bdd1016a4f0473c865e0e63e.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(389, 'cases', 'mwbl2pu7', '{\"title\":\"Penambalan Gigi Berlubang\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"doctor\":\"Drg. Tantri Widyarani\",\"year\":\"\",\"problem\":\"Gigi geraham berlubang dan sensitif.\",\"tools\":\"Dental Unit\\nExcavator\\nResin Komposit\",\"desc\":\"Restorasi gigi dilakukan untuk memperbaiki struktur gigi dan membantu mengembalikan fungsi pengunyahan.\",\"img\":\"/uploads/14354c600daf3674c9c70d1d82d6cd3f.jpg\",\"imgpos\":\"50% 50%\",\"afterimg\":\"\",\"afterimgpos\":\"50% 50%\",\"consent\":true,\"status\":\"Tampil\",\"ord\":\"\"}'),
(235, 'catalog', 'mvyz2opl', '{\"title\":\"Radiologi Gigi\",\"dept\":\"Radiologi Gigi\",\"desc\":\"Radiologi gigi merupakan pemeriksaan penunjang menggunakan teknologi X-Ray untuk membantu dokter mengevaluasi kondisi gigi, jaringan pendukung, dan rongga mulut secara lebih detail. Layanan meliputi rontgen dental, panoramic, cephalometric, TMJ, dan CBCT.\",\"img\":\"/uploads/76bf17024826e0f34547fbb058225195.jpg\",\"imgpos\":\"50% 0%\",\"pdf\":\"/uploads/8c31eea2c10fed5f85e4ffd1e58e8935.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Radiologi\",\"status\":\"Tampil\",\"ord\":\"1\"}'),
(241, 'catalog', 'mw07qo74', '{\"title\":\"Konservasi Gigi\",\"dept\":\"Konservasi Gigi / Endodontic\",\"desc\":\"Perawatan konservasi gigi bertujuan mengembalikan fungsi pengunyahan dan estetika, menghilangkan penyebab rasa sakit, serta mempertahankan gigi agar tetap berfungsi selama mungkin. Layanan mencakup restorasi GIC, composite resin, restorasi indirek, dan perawatan saluran akar.\",\"img\":\"/uploads/b759531620f751c804a7a19847997eb0.jpg\",\"imgpos\":\"50% 16%\",\"pdf\":\"/uploads/341e9541a2077e252b1d291a3ea42202.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Konservasi\",\"status\":\"Tampil\",\"ord\":\"2\"}'),
(242, 'catalog', 'mw07tn2z', '{\"title\":\"Jaringan Penyangga Gigi\",\"dept\":\"Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Perawatan periodontal berfokus pada kesehatan gusi dan jaringan pendukung gigi untuk menjaga kesehatan jangka panjang. Layanan meliputi painless scaling, root planing, scaling airflow, kuretase periodontal, dan perawatan jaringan periodontal lainnya.\",\"img\":\"/uploads/b2122049a28a6dec8f02120147676be4.jpg\",\"imgpos\":\"50% 15%\",\"pdf\":\"/uploads/cd4e15c76b3bb2ea02bdad73ddfb8280.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Perawatan Gusi\",\"status\":\"Tampil\",\"ord\":\"3\"}'),
(243, 'catalog', 'mw07w7x7', '{\"title\":\"Pembuatan Gigi Palsu\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"desc\":\"Perawatan prostodonti berfokus pada pemulihan fungsi dan estetika gigi yang hilang atau rusak. Layanan meliputi inlay, onlay, crown, bridge, gigi tiruan lepasan, serta berbagai restorasi untuk meningkatkan fungsi pengunyahan dan kualitas hidup pasien.\",\"img\":\"/uploads/0ec7de24945a1bfcfba33d64a7762039.jpg\",\"imgpos\":\"50% 16%\",\"pdf\":\"/uploads/8e1533e73216ffd4ee58186607571b34.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Gigi Palsu\",\"status\":\"Tampil\",\"ord\":\"4\"}'),
(244, 'catalog', 'mw07xzk5', '{\"title\":\"Bedah Mulut\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"desc\":\"Bedah mulut merupakan layanan tindakan pembedahan dalam kedokteran gigi untuk menangani kondisi tertentu pada gigi dan jaringan rongga mulut. Layanan meliputi odontektomi atau operasi gigi geraham bungsu, bedah minor, frenektomi, operkulektomi, dan penanganan kista.\",\"img\":\"/uploads/f95a16ba38f29bf615d643e29c44ef89.jpg\",\"imgpos\":\"50% 17%\",\"pdf\":\"/uploads/47a69725037472439f28a5db6f00b6f7.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Bedah Mulut\",\"status\":\"Tampil\",\"ord\":\"5\"}'),
(245, 'catalog', 'mw07zj4o', '{\"title\":\"Meratakan Gigi\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Perawatan ortodonti bertujuan memperbaiki susunan dan posisi gigi agar lebih rapi serta meningkatkan fungsi pengunyahan dan estetika. Layanan mencakup perawatan braces atau kawat gigi, termasuk ORMCO Metal, Damon Metal, dan Damon Clear.\",\"img\":\"/uploads/a21c37b5b9c889c1afecce726b49a3cd.jpg\",\"imgpos\":\"50% 17%\",\"pdf\":\"/uploads/6cffe96f7b696d89d1da418fff6d5da3.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Kawat Gigi\",\"status\":\"Tampil\",\"ord\":\"6\"}'),
(246, 'catalog', 'mw0824vj', '{\"title\":\"Perawatan Gigi Anak\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"desc\":\"Pedodonsia merupakan layanan kedokteran gigi anak yang dirancang untuk memberikan pengalaman perawatan gigi yang nyaman dan menyenangkan. Layanan meliputi imunisasi gigi anak dengan fluoride, penambalan gigi anak, serta berbagai tindakan pencegahan dan perawatan gigi anak.\",\"img\":\"/uploads/d94806f49c51c3ecb0afab2f579d8ff5.jpg\",\"imgpos\":\"50% 17%\",\"pdf\":\"/uploads/7e45ceaf5247cdc6303666a182503fc3.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Gigi Anak\",\"status\":\"Tampil\",\"ord\":\"7\"}'),
(247, 'catalog', 'mw0egds8', '{\"title\":\"Spesial Care Dental Center\",\"dept\":\"Lainnya / Other\",\"desc\":\"Special Care Dental Center menyediakan pendekatan khusus untuk pasien yang membutuhkan perawatan gigi dengan kenyamanan ekstra, termasuk pasien dengan kecemasan tinggi, fobia jarum, refleks muntah berlebih, gigi sensitif, dan pasien berkebutuhan khusus. Perawatan dilakukan dengan pendekatan komunikasi yang lembut dan ramah.\",\"img\":\"/uploads/be34f8e6f727561f4a520960d226394b.jpg\",\"imgpos\":\"50% 25%\",\"pdf\":\"/uploads/c7381adcc369225530b707e562065aed.pdf\",\"price\":\"\",\"dur\":\"\",\"badge\":\"Spesial Care\",\"status\":\"Tampil\",\"ord\":\"8\"}'),
(57, 'departments', 'muz8q2ul', '{\"name\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"latin\":\"General Practitioner\",\"desc\":\"Layanan dokter gigi umum mencakup pemeriksaan, pencegahan, dan penanganan berbagai masalah gigi serta mulut, seperti gigi berlubang, karang gigi, sakit gigi, dan gangguan gusi.\",\"icon\":\"🩺\",\"img\":\"\",\"ord\":\"7\",\"tag\":\"Senyum sehat dimulai dari perawatan gigi yang tepat. Palapa Dentists hadir untuk membantu menjaga kesehatan gigi dan mulut Anda melalui pelayanan dokter gigi umum yang profesional, nyaman, dan sesuai dengan kebutuhan setiap pasien.\",\"about\":\"Layanan perawatan gigi umum merupakan pelayanan kesehatan gigi dan mulut yang berfokus pada pemeriksaan, pencegahan, diagnosis, serta penanganan berbagai masalah gigi dan mulut. Dokter gigi umum di Palapa Dentists melayani berbagai kondisi, mulai dari gigi berlubang, karang gigi, sakit gigi, gangguan gusi, hingga perawatan gigi rutin untuk menjaga kesehatan dan kebersihan rongga mulut.\",\"notet\":\"\",\"note\":\"\",\"treat\":\"Konsultasi Dental\\nKonsultasi Spesialis\\nScaling\\nPenambalan\\nBleaching\"}'),
(234, 'departments', 'mvyz02a3', '{\"name\":\"Radiologi Gigi / Dental Radiology\",\"latin\":\"Dental Radiology\",\"desc\":\"Pemeriksaan penunjang menggunakan teknologi X-Ray untuk membantu dokter mengevaluasi kondisi gigi, jaringan pendukung, dan rongga mulut secara lebih detail.\",\"tag\":\"Radiologi gigi membantu dokter melihat kondisi gigi dan jaringan pendukung yang tidak dapat diketahui hanya melalui pemeriksaan klinis biasa.\",\"about\":\"Pemeriksaan radiologi gigi berperan penting dalam membantu dokter gigi memperoleh gambaran kondisi gigi dan jaringan di sekitarnya secara lebih menyeluruh. Melalui teknologi pencitraan digital, dokter dapat mengevaluasi posisi gigi, kondisi akar, struktur tulang rahang, serta mendeteksi kelainan yang memerlukan penanganan lebih lanjut.\\n\\nSetiap jenis pemeriksaan radiologi dipilih berdasarkan kebutuhan klinis pasien, sehingga hasil pencitraan dapat digunakan sebagai dasar dalam menentukan diagnosis dan menyusun rencana perawatan yang sesuai.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu mendeteksi kelainan gigi dan rahang.\\n- Mendukung ketepatan diagnosis dokter gigi.\\n- Membantu perencanaan tindakan perawatan.\\n- Memberikan gambaran kondisi gigi secara lebih detail.\",\"treat\":\"Rontgen Dental\\nRontgen Panoramik\\nRontgen Cephalometric\\nPaket Rontgen Panoramik dan Cephalometric\\nRontgen TMJ\\nRontgen CBCT\\nPaket CBCT Full Scan 5 x 5,5\\nPaket CBCT Full Scan 8 x 8\\nPaket CBCT Half Scan\\nPaket CBCT Fullscan 11 x 10\\nRontgen CBCT Half Scan\",\"icon\":\"🔬\",\"img\":\"\",\"ord\":\"8\"}'),
(51, 'departments', 's2', '{\"name\":\"Konservasi Gigi / Endodontic\",\"latin\":\"Endodontic\",\"desc\":\"Perawatan untuk memperbaiki gigi berlubang, rusak, atau terinfeksi dengan tujuan mempertahankan gigi alami, mengembalikan fungsi pengunyahan, serta meningkatkan estetika gigi.\",\"ord\":\"1\",\"icon\":\"🛡️\",\"img\":\"\",\"tag\":\"Konservasi gigi berfokus pada upaya mempertahankan gigi alami agar tetap sehat, berfungsi, dan nyaman digunakan selama mungkin.\",\"about\":\"Konservasi gigi merupakan layanan yang bertujuan mempertahankan gigi alami melalui berbagai prosedur restorasi dan perawatan jaringan pulpa. Layanan ini mencakup penambalan gigi, perawatan saluran akar, serta tindakan estetika seperti bleaching.\\n\\nPerawatan dilakukan dengan menyesuaikan tingkat kerusakan gigi, kondisi pulpa, dan jaringan pendukungnya. Dengan penanganan yang tepat, gigi yang mengalami kerusakan masih dapat dipertahankan sesuai dengan indikasi klinis.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu mempertahankan gigi alami.\\n- Memulihkan fungsi pengunyahan.\\n- Membantu menangani kerusakan jaringan gigi.\\n- Mendukung kesehatan dan kenyamanan gigi.\\n- Memperbaiki estetika gigi melalui perawatan tertentu.\",\"treat\":\"Tambalan Resin Komposit Tipe I\\nTambalan Resin Komposit Tipe II\\nTumpatan GIC (Tipe 1)\\nEndodontik Tunggal (kunjungan)\\nEndodontik Ganda\\nOne Visit Endodontik Tunggal / PSA + Pengisian\\nBleaching Intra Corona\\nOffice Bleaching\\nHome Bleaching\\nVeneer Resin Komposit\\nAnestesi\\nOpen Bur / Buka akses\\nTumpatan Sementara\\nMedikasi + TS\\nRetreatment Endodontik Tunggal (kunjungan)\\nRetreatment Endodontik Ganda\\nEndodontik Waveone (Paket)\\nEndodontik Waveone Senior (Paket)\\nRetreatment PSA WaveOne (Paket)\\nApeksifikasi\\nAplikasi Rubber Dam\\nDesensitisasi Dentin\\nGIC LC Base\\nTumpatan GIC (Tipe 2)\\nTumpatan GIC (Tipe 3)\\nArtificial Wall GIC/Resin\\nTambalan Resin Komposit Tipe III\\nTambalan Resin Komposit Pasca PSA\\nDirect Onlay Composite\\nAplikasi MTA\\nAplikasi BioDentine\\nApexreseksi\\nApexreseksi + MTA\\nGingivektomi per Regio\\nGingivektomi per Gigi\\nClip F\\nTambalan Resin Komposit Komplex\\nBongkar Amalgam\\nBongkar Tambalan\\nEkstraksi Fraktur Mahkota\\nTambalan Resin Komposit Dyract\\nGIC Pasca PSA\\nTumpatan Sementara P04\\nTumpatan Sementara IRM\\nTambalan Sementara + Medikasi\\nTumpatan Sandwich (GIC + RK)\\nPengisian Akar Tunggal GP\\nPengisian Akar Ganda GP\\nPengisian Akar Tunggal\\nPengisian Akar Ganda\\nOne Visit Endodontik Ganda / PSA + Pengisian\\nEndodontik Tunggal GP\\nEndodontik Ganda GP\"}'),
(52, 'departments', 's3', '{\"name\":\"Meratakan Gigi / Orthodontic\",\"latin\":\"Orthodontic\",\"desc\":\"Perawatan untuk memperbaiki susunan dan posisi gigi yang tidak teratur menggunakan kawat gigi, clear aligner, serta retainer untuk membantu mendapatkan susunan gigi yang lebih rapi dan fungsi gigitan yang baik.\",\"ord\":\"2\",\"icon\":\"😁\",\"img\":\"\",\"tag\":\"Ortodonsia membantu memperbaiki posisi gigi dan hubungan rahang agar susunan gigi lebih teratur serta mendukung fungsi pengunyahan dan estetika senyum.\",\"about\":\"Ortodonti merupakan layanan yang berfokus pada perbaikan susunan gigi dan hubungan rahang agar mendukung fungsi pengunyahan serta estetika senyum. Perawatan dilakukan dengan menggunakan berbagai perangkat ortodonti, baik berupa bracket konvensional, self-ligating, maupun aligner transparan.\\n\\nSetiap pasien memiliki kondisi susunan gigi yang berbeda, sehingga pemilihan metode perawatan dilakukan berdasarkan hasil pemeriksaan dokter. Perawatan ortodonti juga memerlukan kontrol berkala untuk memantau perkembangan pergerakan gigi dan memastikan proses perawatan berjalan sesuai rencana.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu memperbaiki susunan gigi.\\n- Mendukung fungsi pengunyahan.\\n- Memperbaiki hubungan antar gigi dan rahang.\\n- Mempermudah pemeliharaan kebersihan gigi.\\n- Mendukung estetika dan kepercayaan diri.\",\"treat\":\"Orthodontic Fix Appliance Metal\\nOrthodontic Damon Metal\\nOrthodontic Damon Clear\\nOrthodontic Self Ligating\\nAligner Klar Treatment Basic\\nOrthodontic Invisalign Intermediate\\nFix Retainer\\nHawley Retainer\\nEssix Retainer\\nKontrol Ortho Metal\\nOrthodontic - Damon Ultima K\\nAligner Klar Treatment Advance\\nAligner Klar Treatment Pro\\nOrthodontic Invisalign Advance\\nAktivator\\nLip Bumper\\nReplacement Braces Metal\\nReplacement Braces Damon Metal\\nReplacement Braces Damon Clear\\nKontrol Ortho Damon\\nRPE Orthodontic Appliance\\nFace Mask\\nPalatal Arch\\nLingual Palatal Arch\\nRing\\nBuccal Tube\\nMolar Band\\nDebonding\\nRe Bond\\nResementasi Band Ortho Lepas\\nButton\\nElastic\\nGanti Kawat\\nReparasi Ortho Lepasan\\nPotong Kawat\\nKontrol Self Ligating\\nKontrol Invisalign\\nKontrol Retainer\\nOrtho Implant Mini Screw\\nReparasi Fix Retainer\\nKontrol Ortho Damon (Luar)\\nKontrol Ortho Metal (Luar)\\nDebonding Luar\\nKontrol Aligner Klar\\nOrthodontic Invisalign Lite\"}'),
(53, 'departments', 's4', '{\"name\":\"Bedah Mulut / Oral Surgery\",\"latin\":\"Oral Surgery\",\"desc\":\"Layanan pembedahan gigi dan rongga mulut untuk menangani gigi impaksi, pencabutan kompleks, jaringan abnormal, serta berbagai kondisi yang membutuhkan tindakan bedah minor.\",\"ord\":\"3\",\"icon\":\"⚕️\",\"img\":\"\",\"tag\":\"Bedah mulut menangani kondisi gigi dan jaringan rongga mulut yang memerlukan tindakan pembedahan dengan perencanaan dan pemeriksaan yang tepat.\",\"about\":\"Layanan bedah mulut mencakup berbagai tindakan yang bertujuan menangani kondisi gigi, gusi, dan jaringan rongga mulut yang memerlukan prosedur bedah. Tindakan dapat dilakukan pada gigi yang mengalami kerusakan berat, gigi dengan posisi tertentu, maupun kondisi jaringan mulut yang membutuhkan penanganan khusus.\\n\\nSebelum tindakan dilakukan, dokter akan mengevaluasi kondisi pasien melalui pemeriksaan klinis dan, apabila diperlukan, pemeriksaan radiologi. Perencanaan yang tepat membantu menentukan jenis tindakan serta mendukung proses perawatan yang aman dan terarah.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu menangani kondisi gigi yang memerlukan tindakan bedah.\\n- Mendukung penanganan gigi yang sulit dicabut.\\n- Membantu mengatasi masalah jaringan rongga mulut.\\n- Mendukung kesehatan dan fungsi rongga mulut.\\n- Memberikan perencanaan tindakan sesuai kondisi pasien.\",\"treat\":\"Ekstraksi gigi permanen\\nEkstraksi dengan Penyulit\\nOdontectomy Kelas I\\nOdontectomy Kelas II\\nOdontectomy Kelas III\\nFrenectomy\\nOperculectomy\\nImplant Dentium\\nImplant NTI\\nSinus Lifting\\nEkstraksi komplikasi\\nOdontectomy Kelas IIIC\\nOperasi Mucocele\\nInsisi / Eksisi\\nDry Socket\\nTindakan Jahit\\nKontrol / Buka jahitan\\nKontrol / Buka jahitan Odontectomy\\nWindowing\\nBuka jahitan kompleks\\nAplikasi Collagen\\nOperasi Coronektomy\\nEnukleasi Kista\\nEkstraksi Radiks\\nEkstraksi komplex dengan jahitan\\nBone graft (Gamacha)\\nBone graft (Batan)\\nBone graft (Osteon)\\nAlveolectomy\\nBedah Minor\\nBantuan Oksigen\"}'),
(54, 'departments', 's5', '{\"name\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"latin\":\"Prosthodontic\",\"desc\":\"Perawatan untuk menggantikan gigi yang hilang atau memperbaiki gigi yang rusak melalui gigi tiruan dan restorasi, guna mengembalikan fungsi pengunyahan, estetika, serta kenyamanan pasien.\",\"ord\":\"4\",\"icon\":\"🦷\",\"img\":\"\",\"tag\":\"Prostodonsia membantu mengembalikan fungsi dan estetika senyum melalui berbagai pilihan gigi tiruan dan restorasi yang disesuaikan dengan kondisi gigi pasien.\",\"about\":\"Kehilangan gigi dapat memengaruhi kemampuan mengunyah, berbicara, serta kenyamanan dalam menjalani aktivitas sehari-hari. Prostodonsia menyediakan berbagai pilihan restorasi dan gigi tiruan untuk membantu mengembalikan fungsi gigi yang hilang atau mengalami kerusakan.\\n\\nJenis perawatan meliputi gigi tiruan lepasan, restorasi cekat seperti crown dan bridge, veneer, serta berbagai pilihan bahan restorasi yang disesuaikan dengan kebutuhan pasien. Perencanaan dilakukan dengan mempertimbangkan kondisi gigi, jaringan pendukung, fungsi pengunyahan, dan aspek estetika.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu mengembalikan fungsi pengunyahan.\\n- Mendukung kejelasan berbicara.\\n- Memperbaiki estetika senyum.\\n- Membantu menjaga keseimbangan fungsi gigi.\\n- Memberikan pilihan restorasi sesuai kebutuhan pasien.\",\"treat\":\"GTSL Akrilik (Plat + Gigi Pertama)\\nValplast (Plat + Gigi Pertama)\\nGigi Tiruan Penuh Plat Akrilik (GTP)\\nGTSKL (Frame + Gigi Pertama)\\nInlay / Onlay / Crown / Bridge Metal\\nInlay / Onlay / Crown / Bridge Metal Porcelain\\nInlay / Onlay / Crown / Bridge IPS e.max\\nInlay / Onlay / Crown / Bridge All Porcelain Zircon\\nVeneer All Porcelain\\nNight Guard\\nKonsultasi / Cetak TMJ\\nSplint TMJ Removable\\nCetak studi model Alginate per Rahang\\nCetak rubber base single\\nCetak Alginate RA & RB\\nCetak Rubber Base RA & RB\\nSementasi Metal (GIC)\\nSementasi All Porcelain (Resin)\\nGTSL Thermosen\\nGTSKL Kombinasi Thermosen\\nGTSKL Kombinasi Valplast\\nGTSKL Kombinasi Akrilik\\nGigi Tambahan GTS\\nGigi Tiruan Penuh Plat Logam\\nSendok Cetak Perseorangan (SCP)\\nTambah Elemen - Gigi\\nTambah Klamer\\nRebasing/Relaining\\nPIN Customize\\nPIN Custom made / Fibre Post Kleer\\nCore Build Up - Core Resin Tanpa pasak\\nBongkar Crown tanpa Bur\\nBongkar Crown dgn Bur\\nCrown Temporary\\nCrown Temporary Direct\\nCrown Lengthening\\nInlay / Onlay / Crown / Bridge Adoro\\nKontrol GTP\\nKontrol GTS\\nPin Metal\\nSplinting Fiber Komposit\\nResementasi Inlay/Onlay/Crown\\nCrown Sementara Structur\\nMahkota Tiruan Sementara (RK)\\n3D Scan TRIOS\\nSementasi Sementara\\nBridge Maryland\\nReparasi Gigi Tiruan\\nCrown Bridge Metal Akrilik\\nCrown / Bridge Akrilik\\nIndirect Veneer dengan Ceramic Zircon\"}'),
(55, 'departments', 's6', '{\"name\":\"Jaringan Penyangga Gigi / Periodontic\",\"latin\":\"Periodontic\",\"desc\":\"Perawatan gusi dan jaringan pendukung gigi untuk mengatasi peradangan, infeksi periodontal, gusi turun, serta menjaga kestabilan gigi.\",\"ord\":\"5\",\"icon\":\"🧬\",\"img\":\"\",\"tag\":\"Periodonsia membantu menjaga kesehatan gusi dan jaringan pendukung gigi agar gigi tetap stabil serta terhindar dari kerusakan jaringan periodontal lebih lanjut.\",\"about\":\"Kesehatan jaringan periodontal memiliki peran penting dalam menjaga kekuatan dan kestabilan gigi. Gangguan pada gusi dan jaringan penyangga gigi dapat menyebabkan ketidaknyamanan serta memengaruhi kondisi gigi dalam jangka panjang.\\n\\nLayanan periodonsia mencakup perawatan untuk membantu mengatasi penumpukan plak dan karang gigi, peradangan gusi, serta berbagai kondisi jaringan periodontal lainnya. Penanganan dilakukan berdasarkan hasil pemeriksaan dan tingkat keparahan kondisi pasien.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Membantu menjaga kesehatan gusi.\\n- Mengurangi penumpukan plak dan karang gigi.\\n- Membantu menjaga kestabilan gigi.\\n- Mendukung pemeliharaan kesehatan jaringan periodontal.\\n- Membantu mencegah perkembangan penyakit gusi.\",\"treat\":\"Scaling Kls I RA & RB\\nScaling Kls II RA & RB\\nScaling Kls III RA & RB\\nScaling dgn Airflow RA & RB\\nDeep Scaling / Root Planing\\nPolishing Stain\\nCuretase\\nFlap Operation\\nGingivektomi\\nSplinting (Wire Ligature / Komposit)\\nScaling Kls IIIC RA & RB\\nAblasi (Bleaching Gusi)\\nFlap Operation per Regio\\nOcclusal Adjustment\\nOcclusal Adjustment per Regio\\nCauterisasi\\nGingivektomi per Regio\\nSplinting dengan Ribon\\nTindakan Bonegraft Tipe 1\\nTindakan Bonegraft Tipe 2\\nTindakan Membran Tipe 1\\nTindakan Membran Tipe 2\\nAplikasi Metronidazole (Ties)\\nAplikasi Woundressing\\nPendalaman Vestibulum\\nFlap Operation + Bonegraft\\nCuretase + Gingivektomi + Ties Pack\"}'),
(56, 'departments', 's7', '{\"name\":\"Perawatan Gigi Anak / Pedodontic\",\"latin\":\"Pedodontic\",\"desc\":\"Layanan perawatan gigi anak untuk mencegah dan menangani gigi berlubang, menjaga kesehatan gigi susu, serta mendukung pertumbuhan gigi dan rahang anak secara optimal.\",\"ord\":\"6\",\"icon\":\"🧸\",\"img\":\"\",\"tag\":\"Pedodonsia memberikan perawatan gigi anak dengan pendekatan yang ramah dan menyenangkan untuk membantu menjaga kesehatan gigi sejak dini.\",\"about\":\"Pedodonsia tidak hanya berfokus pada perawatan gigi anak, tetapi juga pada pembentukan kebiasaan menjaga kesehatan gigi sejak usia dini. Perawatan dilakukan dengan mempertimbangkan usia, kondisi gigi, serta kebutuhan tumbuh kembang anak.\\n\\nPalapa Dentists mengutamakan pendekatan yang ramah, sabar, dan menyenangkan agar anak merasa lebih nyaman selama menjalani pemeriksaan maupun perawatan. Dengan suasana yang mendukung, anak diharapkan dapat mengenal dokter gigi sebagai bagian dari upaya menjaga kesehatan dirinya.\",\"notet\":\"Manfaat utama:\",\"note\":\"- Menjaga kesehatan gigi susu dan gigi permanen.\\n- Membantu mencegah gigi berlubang sejak dini.\\n- Mendukung pertumbuhan gigi dan rahang anak.\\n- Membentuk kebiasaan perawatan gigi yang baik.\\n- Memberikan pengalaman perawatan yang lebih nyaman bagi anak.\",\"treat\":\"Konsultasi + DHE\\nOral Profilaksis\\nScaling Anak RA & RB\\nTopikal Fluor\\nPit & Fissure Sealant (GIC)\\nTumpatan GIC Tipe I (gigi susu)\\nTumpatan Resin Komposit Tipe I (gigi susu)\\nEkstraksi gigi susu simple\\nMetal Crown\\nSpace Maintainer Removable 1\\nKonsultasi Spesialis + DHE\\nOral Profilaksis Pedo dengan perawatan lain\\nScaling Anak (Complex) RA & RB\\nPit & Fissure Sealant (Flow It)\\nTumpatan GIC Tipe II (gigi susu)\\nTumpatan GIC Tipe III (gigi susu)\\nCompomer Pedo Tipe 1\\nCompomer Pedo Tipe 2\\nCompomer Pedo Tipe 3\\nTumpatan Resin Komposit Tipe II (gigi susu)\\nTumpatan Resin Komposit Tipe III (gigi susu)\\nCompomer Pedo Complex\\nCompomer Pedo Complex Multiple\\nSementasi Pedo\\nResementasi SSC Pedo\\nPulp Capping\\nPulpotomi gigi sulung Anterior\\nPulpotomi gigi sulung Posterior\\nEndodontic gigi sulung Anterior\\nEndodontic gigi sulung Posterior\\nPSA one visit gigi susu Anterior\\nPSA one visit gigi susu Posterior\\nEkstraksi gigi susu dengan anestesi topikal\\nEkstraksi gigi susu persistensi\\nEkstraksi gigi susu dengan penyulit\\nInsisi Abses Pedo\\nSpace Maintainer Removable 2\\nSpace Maintainer Fix 1\\nSpace Maintainer Fix 2\\nRemovable Appliance 1 Rahang\\nRemovable Appliance 2 Rahang\\nIncline bite plane\\nKontrol Removable Appliance Pedo\\nFunctional Appliance (Twin Blok, Bionator)\\nMyobrace\\nBehavioral Manajemen Ringan\\nBehavioral Manajemen Sedang\\nBehavioral Manajemen Berat\\nPaket Myobrace 6 bulan\\nKontrol Myobrace\\nPengisian + GIC gigi susu\\nRestorasi Biofix Pedo\\nCelluloid crown\"}'),
(14, 'doctors', 'muz8rwbo', '{\"name\":\"Drg. Rasyid Abdulaziz\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"Pendidikan Dokter Gigi Fakultas Kedokteran Gigi Universitas Padjadjaran 2024\",\"experience\":\"\",\"sched\":\"Selasa 16:00 - 20:00 & Jumat 13:00 - 15:00\",\"bio\":\"Drg. Rasyid Abdulaziz merupakan lulusan Pendidikan Dokter Gigi Fakultas Kedokteran Gigi Universitas Padjadjaran (Unpad) pada tahun 2024. Selama masa studinya, beliau aktif dalam berbagai kegiatan organisasi, khususnya di Asia Pacific Dental Students Association (APDSA).\\n\\nSelain itu, Drg. Rasyid juga memiliki minat yang besar di bidang penelitian ilmiah dan telah berkontribusi dalam publikasi beberapa artikel pada jurnal internasional, salah satunya berjudul “Whole Exome Sequencing Identifies Damaging Variants in Indonesians with Clefts.”\\n\\nDrg. Rasyid berkomitmen untuk memberikan pelayanan kedokteran gigi yang berkualitas secara evidence-based dengan pendekatan yang hangat dan kekeluargaan kepada pasien. Saat ini, Drg. Rasyid aktif berpraktik sebagai dokter gigi umum di Palapa Dentists, Medikids Pondok Indah, dan Medikids Lebak Bulus.\",\"img\":\"/uploads/0a5623bd18f5734284187a6dc7564d65.jpg\",\"imgpos\":\"50% 32%\",\"active\":true,\"ord\":\"35\"}'),
(15, 'doctors', 'muz8up96', '{\"name\":\"Drg. Natasya Hillary, Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Dokter Gigi Spesialis Konservasi Gigi\",\"degree\":\"S1 & Profesi Fakultas Kedokteran Gigi Universitas Indonesia (2013-2019), S2 Spesialis Konservasi Gigi FKG UI (2021-2024)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 7 tahun, dan Dosen pengajar di Universitas Indonesia\",\"sched\":\"Senin 16:00 - 20:00, Jumat 16:00 - 20:00 & Sabtu 15:00 - 20:00\",\"bio\":\"drg. Natasya Hillary, Sp. KG adalah lulusan dokter gigi Universitas Indonesia, beliau menyelesaikan program sarjana (2013–2017) dan program profesi dokter gigi (2017–2019). Beliau kemudian melanjutkan pendidikan spesialis Konservasi Gigi (Sp.KG) di Universitas Indonesia dan lulus pada tahun 2024 dengan predikat cumlaude. Saat ini, drg. Natasya juga aktif sebagai dosen pengajar di Universitas Indonesia.\\n\\ndrg. Natasya terkenal dengan prestasinya di bidang akademis maupun non akademis, selama di pendidikan drg. Natasya mendapatkan penghargaan cumlaude dalam jenjang S1 maupun Profesi serta memenangkan berbagai kompetisi ilmiah seperti Literature Review, Juara 1 Oral Presentation Case Report KPPIKG 2023, dan Juara 1 Best Case Report Non Surgical Penn Endodontic Global Symposium x IKORGI. Selain itu, beliau juga memiliki publikasi jurnal ilmiah di bidang restorasi gigi dan pernah mengikuti program pertukaran pelajar ke Tokyo Medical and Dental University, Jepang pada tahun 2019.\\n\\nSelain itu, drg. Natasya aktif dalam kegiatan non akademis dengan menjadi ketua BEM FKG UI periode 2015-2016, Pengurus harian organisasi Persatuan Senat Mahasiswa Kedokteran Gigi Indonesia 2014-2016, dan berbagai kepanitiaan ilmiah, non ilmiah, serta berbagai kegiatan Bakti Sosial di dalam dan luar pulau jawa. Sejak lulus hingga sekarang dokter Natasya tergabung dan aktif berpraktik di MHDC Group Holding Company dan Palapa Dentist.\",\"img\":\"/uploads/9b02e916a591ea1d815d60bb934276c8.jpg\",\"imgpos\":\"50% 14%\",\"active\":true,\"ord\":\"27\"}'),
(16, 'doctors', 'muz8xmtj', '{\"name\":\"Drg. Aulia Karina Fitriananda\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2018), S1 Profesi Dokter Gigi FKG UI (2021)\",\"experience\":\"\",\"sched\":\"Senin 09:00 - 15:00 & Selasa 09:00 - 14:00\",\"bio\":\"drg. Aulia Karina Fitriananda merupakan lulusan Pendidikan Fakultas Kedokteran Gigi (FKG) Universitas Indonesia pada tahun 2018. Beliau melanjutkan studinya pada program Profesi Dokter Gigi Umum pada tahun 2018 dan lulus pada tahun 2021. Beliau pernah menjabat sebagai Ketua TRISTIQUE FKG UI 2016, Chief of Health and Consumption dalam Social Project “GUSI 2014,” dan Chief of Fund untuk acara OPEN HOUSE FKG UI 2015. Selain itu, beliau juga terlibat sebagai panitia dalam berbagai acara, seperti Pertemuan Ilmiah dan Kursus Penyegaran Kedokteran Gigi (KPPIKG) 2019, Kerja Sosial (KERSOS) di Labuan Bajo (2018), serta berbagai kegiatan bakti sosial lainnya.\\n\\ndrg. Aulia Aktif berpartisipasi dalam berbagai kegiatan akademik, di antaranya sebagai peserta sekaligus penulis pertama pada International Workshop on Dental Research (IWDR) tahun 2020. Selain itu drg. Aulia juga aktif mengikuti berbagai seminar dan webinar kedokteran gigi sebagai bagian dari pengembangan wawasan dan kompetensi profesional, di antaranya Denstudy Series 1 Session 3 bertema “Tips dan Trik Mencapai Sukses Aesthetic Direct Posterior Restoration” yang diselenggarakan oleh Ummacademy Indonesia pada tahun 2021, Scholarship Class Session 2 bertema “Beasiswa Spesialis Kemenkes: Challenge Yourself and Achieve Your Dreams” yang juga diselenggarakan oleh Ummacademy Indonesia pada tahun 2021, serta Webinar Denstudy Volume 7 bertema “Prosthodontics: Smile Designing” yang diselenggarakan oleh Ummadent Indonesia pada tahun 2020. Selain itu, juga mengikuti webinar “Endometric Endodontic: Working Long Estimation in Endodontic” dan “Supercharged Restoration as Alternative in Pandemic Situation” yang diselenggarakan pada tahun 2021.\\n\\ndrg. Aulia merupakan dokter gigi yang hemat dan berkomitmen untuk memberikan perawatan pasien terbaik melalui komunikasi dan layanan berkualitas tinggi. Saat ini, drg. Arin aktif praktik sebagai dokter gigi di Palapa Dentists.\",\"img\":\"/uploads/e1b10a6672f449de2f5d9dbfd8695163.jpg\",\"imgpos\":\"50% 21%\",\"active\":true,\"ord\":\"23\"}'),
(17, 'doctors', 'muz90k93', '{\"name\":\"Drg. Rista Lewiyonah, Sp. KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Dokter Gigi Spesialis Kedokteran Gigi Anak\",\"degree\":\"S1 & Profesi FKG Universitas Indonesia, S2 Spesialis Ilmu Kedokteran Gigi Anak FKG Universitas Indonesia\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 7 tahun\",\"sched\":\"Jumat 10:00 - 15:00 & Sabtu, Minggu 16:00 - 19:30\",\"bio\":\"drg. Rista merupakan lulusan Program Pendidikan Dokter Gigi Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2018. Beliau kemudian melanjutkan pendidikan Program Spesialis Kedokteran Gigi Anak di Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2020. Selama menjalani pendidikan, drg. Rista aktif berpartisipasi dalam berbagai kegiatan akademik maupun nonakademik sebagai bagian dari pengembangan kompetensi profesional. Drg Rista menyelesaikan pendidikan Spesialis Kedokteran Gigi Anak dengan predikat cumlaude.\\n\\nSetelah menyelesaikan pendidikan dokter gigi dan spesialis, drg. Rista juga secara aktif mengikuti berbagai seminar pelatihan dan khususnya di bidang kedokteran gigi anak untuk memperluas wawasan serta meningkatkan kualitas pelayanan kepada pasien. Saat ini, drg. Rista aktif berpraktik di Palapa Dentists dan Medikids Kemang.\",\"img\":\"/uploads/0026c7c5b075fa0d8d906e3fd927e401.jpg\",\"imgpos\":\"50% 4%\",\"active\":true,\"ord\":\"17\"}'),
(18, 'doctors', 'muzbkemd', '{\"name\":\"Drg. Arsy Muda\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Kedokteran Gigi FKG Universitas Padjajaran (2014), S1 Profesi Dokter Gigi FKG Universitas Padjajaran (2018)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 8 tahun\",\"sched\":\"Senin 16:00 - 20:00, Jumat 09:00 - 14:00 & Minggu 08:00 - 14:00\",\"bio\":\"drg. Asry Muda Madya Pratama atau lebih sering disapa drg. Muda merupakan lulusan Pendidikan Kedokteran Gigi (FKG) Universitas Padjajaran pada tahun 2014. Beliau melanjutkan studinya pada program Profesi Dokter Gigi pada tahun 2014 dan lulus pada tahun 2018. drg. Muda selalu termotivasi untuk memberikan pelayanan terbaik terhadap pasien sesuai dengan kompetensi yang dimiliki. Serta ingin membawa perubahan yang lebih baik khususnya dalam bidang kesehatan gigi.\\n\\ndrg. Muda juga Aktif mengikuti berbagai seminar dan pelatihan di bidang kedokteran gigi sebagai bagian dari pengembangan kompetensi profesional, di antaranya International Indonesian Pediatric Dentistry Association Conference tahun 2025, Advance Course on Dental Anesthesia tahun 2023, serta pelatihan Odontektomi Sederhana dan Ekstraksi dengan Flap sebagai peserta hands-on yang diselenggarakan oleh Persatuan Dokter Gigi Indonesia cabang Kota Bandung pada tahun 2018. Selain itu, ia juga mengikuti Asian Endodontic Congress (AEC) yang diselenggarakan oleh Ikatan Konservasi Gigi Indonesia pada tahun 2016, pelatihan hands-on “Rahasia Restorasi Komposit yang Estetika dan Tahan Lama” yang diselenggarakan oleh Fakultas Kedokteran Gigi Universitas Padjadjaran pada tahun 2015, serta seminar “Teknik Baru untuk Meningkatkan Akses, Mengurangi Instrumen dan Waktu Kerja di Endodontik” yang diselenggarakan oleh Ikatan Konservasi Gigi Indonesia cabang Kota Bandung pada tahun 2014.\\n\\nMemiliki pengalaman sebagai dokter gigi selama lebih dari 8 tahun. Saat ini, drg. Muda aktif Berpraktik sebagai dokter gigi umum di Palapa Dentist, Medikids Pondok Indah, dan Medikids Bintaro.\",\"img\":\"/uploads/efb4cb201aba60e11602465fdcfa57f6.jpg\",\"imgpos\":\"50% 8%\",\"active\":true,\"ord\":\"28\"}'),
(19, 'doctors', 'muzbpkfq', '{\"name\":\"Drg. Triana Sari Putri, Sp.KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Perawatan Gigi Anak\",\"degree\":\"S1 & Profesi dokter Gigi FKG UI (1990-1996) dan S2 PPDGS Ilmu Kesehatan Gigi Anak FKG UI (2007-2010)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 12 tahun\",\"sched\":\"Senin 09:00 - 13:00 & Minggu 08:30 - 13:00\",\"bio\":\"Drg. Triana Sari Putri, Sp.KGA adalah dokter gigi spesialis kedokteran gigi anak yang berpraktik di beberapa klinik gigi, termasuk Dokter Gigi Palapa. Beliau menyelesaikan pendidikan Profesi Dokter Gigi di Universitas Indonesia pada tahun 2006 dan melanjutkan pendidikan Spesialis Kedokteran Gigi Anak di universitas yang sama pada tahun 2010.\\n\\nDrg. Triana fokus pada pencegahan dan perawatan penyakit gigi dan mulut pada anak. Berpengalaman Lebih dari 12 tahun membantu pasien anak menjaga kesehatan gigi dan mulut melalui layanan seperti cabut gigi, tambal gigi, dan perawatan lainnya.\\n\\nDrg. Triana juga tergabung dalam organisasi profesional seperti Persatuan Dokter Gigi Indonesia (PDGI) dan Ikatan Dokter Gigi Anak Indonesia (IDGAI). Dengan pengalaman dan keahliannya, drg. Triana Sari Putri, Sp.KGA dapat menjadi pilihan yang tepat untuk kebutuhan kesehatan gigi anak Anda\",\"img\":\"/uploads/20364782efc9fe0fcb825f1f4a4648e1.jpg\",\"imgpos\":\"50% 31%\",\"active\":true,\"ord\":\"5\"}'),
(20, 'doctors', 'muzbxgm2', '{\"name\":\"Drg. Valeria Widita Wairooy Sp. KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Dokter Gigi Spesialis Konservasi Gigi\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2008-2012) dan S1 Profesi Kedokteran Gigi FKG UI (2012-2014)\",\"experience\":\"Dosen Departemen Konservasi Gigi FKG UI, Dokter Gigi Spesialis Konservasi Gigi Klinik Dokter Gigi Palapa (Sekarang)\",\"sched\":\"Senin & Kamis 16:00 - 20:00\",\"bio\":\"drg. Valeria Widita Wairooy, Sp.KG atau kerap disapa drg. Dita merupakan lulusan Program Pendidikan Dokter Gigi Fakultas Kedokteran Gigi Universitas Indonesia (FKG UI) pada tahun 2012. Setelah menyelesaikan Program Profesi Dokter Gigi di universitas yang sama pada tahun 2014, drg. Dita melanjutkan spesialis pendidikan di bidang Konservasi Gigi di FKG UI pada tahun 2020.\\n\\ndrg. Dita juga aktif mengikuti berbagai seminar dan pelatihan di bidang konservasi gigi dan endodontik untuk terus memperbarui pengetahuan serta keterampilan klinisnya. Beberapa kegiatan ilmiah yang pernah diikuti antara lain Penn Endodontic Global Symposium bekerja sama dengan IKORGI Jakarta Pusat (2025), Seminar & Hands-On ENDONESIA 4.5 (2024), Conservative Dentistry Scientific Meeting (2023), serta Seminar & Hands-On KPPIKG (2023). Selain itu, drg. Dita juga mengikuti Seminar SINI V (2022), Endogeek SC (2021), 12th IFEA (2020), dan Dental Insight: Endonesia Returns (2020).\\n\\nBerpengalaman sebagai dokter gigi selama lebih dari 12 tahun. Saat ini, drg. Dita aktif berpraktik di Dokter Gigi Palapa dan RSKGM Universitas Indonesia. Selain menjalani praktik klinis, drg. Dita juga aktif sebagai dosen di Departemen Konservasi Gigi FKG UI.\\n\\n\",\"img\":\"/uploads/3ffdc5ad5e2842eeed2dc7e23e1cf64e.jpg\",\"imgpos\":\"50% 22%\",\"active\":true,\"ord\":\"15\"}'),
(21, 'doctors', 'mv0pylox', '{\"name\":\"Drg. Sasi Suci Ramadhani, Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"degree\":\"S1 Profesi Dokter Gigi Universitas Jember (2007) dan S2 Spesialis Konservasi Gigi FKG UI (2019)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 19 tahun\",\"sched\":\"Selasa 13:00 - 15:00, Rabu 09:00 - 12:00 & Jumat 15:00 - 20:00\",\"bio\":\"drg. Sasi Ramadhani, Sp.KG menyelesaikan pendidikan Spesialis Konservasi Gigi di Universitas Indonesia dan lulus pada tahun 2019.\\n\\ndrg. Sasi juga aktif mengikuti berbagai kegiatan seminar, pelatihan, dan kursus ilmiah di bidang endodontik serta restoratif, baik nasional maupun internasional, seperti International Federal of Endodontic Association (IFEA), IDEC Academy, Seminar Ilmiah Nasional (SINI) IKORGI, hingga berbagai masterclass restorative course.\\n\\nBerpengalaman lebih dari 20 tahun sebagai dokter gigi, dan fokus dalam perawatan konservasi gigi, khususnya perawatan saluran akar, restorasi estetik, dan rehabilitasi gigi dengan pendekatan minimal invasif untuk menjaga fungsi serta kesehatan gigi pasien secara optimal. Saat ini, drg. Sasi aktif praktik sebagai dokter gigi di beberapa klinik gigi jakarta, termasuk Klinik Dokter Gigi Palapa.\\n\\n\",\"img\":\"/uploads/f06b797961be1e2de7317a4330ecdaff.jpg\",\"imgpos\":\"50% 23%\",\"active\":true,\"ord\":\"21\"}');
INSERT INTO `docs` (`rid`, `col`, `id`, `data`) VALUES
(22, 'doctors', 'mv0q2xtd', '{\"name\":\"Drg. Priska Angelia B, Sp.KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Perawatan Gigi Anak\",\"degree\":\"S1 Profesi Kedokteran Gigi FKG Universitas Trisakti (2017) dan S2 Spesialis Pedodontic FKG Universitas Padjadjaran (2022)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 5 tahun\",\"sched\":\"Senin 09:00 - 14:00 & Sabtu 08:00 - 13:00\",\"bio\":\"drg. Priska Menyelesaikan pendidikan Sarjana Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Trisakti pada tahun 2017. Setelah menyelesaikan pendidikan profesi, beliau kemudin melanjutkan pendidikan spesialis di bidang Pedodontic di Fakultas Kedokteran Gigi Universitas Padjadjaran pada tahun 2022. Salah satu prestasi drg. Priska di bidang akademic yaitu berhasil meraih Juara ke-3 dalam Scientific Research Competition pada Kongres APDSA ke-39 yang diselenggarakan di Cairns, Australia.\\n\\nUntuk memperdalam kompetensi, drg. Priska telah menyelesaikan kursus pendidikan berkelanjutan di Temple University Kornberg School of Dentistry, Amerika Serikat, pada tahun 2022. Selain keahlian medis, drg. Priska memiliki kepedulian tinggi terhadap inklusivitas yang dibuktikan dengan partisipasi aktif dalam Program Kelas Bahasa Isyarat (PUSBINDO) sejak tahun 2024 hingga sekarang.\\n\\nSecara klinis, drg. Priska memiliki keahlian mendalam dalam berbagai prosedur kedokteran gigi, termasuk rehabilitasi mulut, perawatan restoratif estetik, ortodonti interseptif, perawatan saluran akar, hingga penanganan trauma gigi. Saya memiliki fokus khusus pada perawatan anak berkebutuhan khusus, yang didukung oleh kemampuan komunikasi efektif, manajemen waktu yang baik, dan pola pikir kritis.\",\"img\":\"/uploads/7880a055369f40588d2dd06ad81de06e.jpg\",\"imgpos\":\"50% 16%\",\"active\":true,\"ord\":\"22\"}'),
(23, 'doctors', 'mv0q7w75', '{\"name\":\"Drg. Fathia Agzarine Deandra, Sp. Perio\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 & Profesi Kedokteran Gigi FKG UI (2011-2017)\",\"experience\":\"\",\"sched\":\"Selasa 10:00 - 14:00, Rabu 16:00 - 20:00 & Jumat 16:00 - 20:00\",\"bio\":\"Dokter Gigi Fathia merupakan lulusan Pendidikan Kedokteran Gigi (FKG) Universitas Indonesia pada tahun 2017. Selama menempuh Pendidikan Kedokteran Gigi, drg. Fathia banyak berpartisipasi dalam kegiatan Akademis maupun non-Akademis seperti menjadi perwakilan Universitas Indonesia dalam ajang Dentsply Academy Research Competition pada tahun 2015. Setelah mendapatkan gelar Dokter Gigi, drg. Fathia serta aktif mengikuti berbagai macam seminar kedokteran gigi, baik di dalam maupun luar negeri seperti Aesthetic & Restorative Masterclass dan Essential Hands on Skills for Minor Oral Surgery in General Dental Practice , di Kings College, London pada tahun 2020. Selain itu, drg. Fathia juga menempuh pendidikan singkat dalam bidang Organizational Resources Management in Health and Social Care di Oxford Brookes University. Saat ini, drg. Fathia bekerja sebagai Dokter Gigi Umum di Palapa Dentists dan Medikids Kemang.\",\"img\":\"/uploads/4dbff0d4275d44eb0edbde227841f889.jpg\",\"imgpos\":\"50% 65%\",\"active\":true,\"ord\":\"19\"}'),
(24, 'doctors', 'mv0qhb4d', '{\"name\":\"Drg. Teuku Ahmad Arbi, Sp.BMM, Subsp.IDM(K)\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"spec\":\"Bedah Mulut\",\"degree\":\"S1 Kedokteran Gigi FKG UI (1996 – 2002) dan S2 Spesialis Bedah Mulut dan Maksilofasial FKG UI (2007-2012)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 20 tahun\",\"sched\":\"Selasa 16:00 - 20:00, Jumat 09:00 - 11:00 & Minggu 08:30 - 20:00\",\"bio\":\"drg. Arbi merupakan lulusan Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2002. Sebelum melanjutkan studi S2-nya, drg. Arbi mengikuti PTT di Pusat Kesehatan Mahasiswa sebagai Dokter Gigi Umum pada tahun 2003 hingga 2007. Selesai mengikuti PTT, drg. Arbi melanjutkan pendidikannya dengan mengambil spesialisasi Bedah Mulut dan Maksilofasial di FKG UI pada tahun 2012 dengan predikat lulusan tercepat. Keinginannya dalam membantu sesama khususnya kasus kedaruratan di ruang lingkup Maksilofasial, menjadi alasan utama Beliau memilih spesialisasi Bedah Mulut dan Maksilofasial.\\n\\ndrg. Arby juga aktif mengikuti berbagai kursus untuk mendukung pengembangan kompetensi di bidang bedah mulut dan maksilofasial, di antaranya Advance Trauma Life Support oleh IKABI, Total Nutrition Therapy and Perioperative Critical Care Management oleh Collegium of Anesthesiology and Reanimation pada tahun 2009, serta Principles of Craniomaxillofacial Fracture Management oleh AOCMF Asia Pacific pada tahun 2010. Selain itu, juga mengikuti pelatihan National Bonegraft Technology and Implementation di Universitas Gajah Mada pada tahun 2013, Advances Course on Condyle, Midface and Orbit Reconstruction with Anatomical Specimens oleh AOCMF Asia Pacific pada tahun yang sama, serta Basic Microsurgery Course in Oral and Maxillofacial Approach yang diselenggarakan oleh Department of Oral and Maxillofacial Surgery Universitas Indonesia bekerja sama dengan Kagoshima University pada tahun 2019.\\n\\nDalam praktiknya sebagai Dokter Gigi, drg. Arbi fokus pada kasus Bedah Dento Alveolar, Implan Gigi, dan Trauma Maksilofasial. Saat ini, selain aktif menjadi Spesialis Bedah Mulut dan Maksilofasial di Palapa Dentists, drg. Arbi juga aktif sebagai Staf Pengajar dan Wakil Dekan III Fakultas Kedokteran Gigi (FKG) Universitas Syiah Kuala, Banda Aceh.\",\"img\":\"/uploads/b776dd29e3fb849921e0db6d59b9b137.jpg\",\"imgpos\":\"50% 23%\",\"active\":true,\"ord\":\"7\"}'),
(25, 'doctors', 'mv4pxu8r', '{\"name\":\"Drg. Andiana Rizqi Indirayani, Sp. KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2012) , S1 Profesi Dokter Gigi FKG UI (2014) dan S2 Spesialis Konservasi Gigi FKG UI (2025)\",\"experience\":\"\",\"sched\":\"Selasa, Kamis 16:00 - 20:00 & Sabtu 13:00 - 15:00\",\"bio\":\"drg. Andiana Rizqi Indirayani, Sp.KG, atau yang akrab disapa drg. Dian, merupakan lulusan Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2012. Beliau kemudian melanjutkan Program Profesi Dokter Gigi dan menyelesaikannya pada tahun 2014. Untuk memperdalam kompetensi di bidang kedokteran gigi konservasi, drg. Dian melanjutkan pendidikan spesialis Konservasi Gigi pada tahun 2022 dan menyelesaikannya pada tahun 2025.\\n\\nMemiliki pengalaman sebagai dokter gigi selama lebih dari 12 tahun. Saat ini, drg. Dian aktif Berpraktik sebagai dokter gigi umum di Palapa Dentist dan Medikids Pondok Indah.\",\"img\":\"/uploads/e965405d7e72be944e336a78adff39f2.jpg\",\"imgpos\":\"50% 37%\",\"active\":true,\"ord\":\"18\"}'),
(26, 'doctors', 'mv4qdutn', '{\"name\":\"Drg. Efrina Ayudyah Paramitha, Sp. Ort\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"spec\":\"Spesialis Ortodonsia\",\"degree\":\"Program pendidikan kedokteran gigi 2006-2011, Program pendidikan dokter gigi spesialis ortodonsia 2013-2017\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 13 tahun\",\"sched\":\"Kamis 16:00 - 20:00 & Sabtu 08:00 - 13:00\",\"bio\":\"drg. Efrina Ayudyah Paramitha, Sp. Ort. merupakan lulusan Fakultas Kedokteran Gigi Universitas Indonesia  dengan spesialisasi ortodonsia.\\n\\nSaat menjalani pendidikan kedokteran gigi drg efrina aktif dalam berbagai kegiatan kemahasiswaan dan pernah menjabat sebagai Bendahara di Badan Eksekutif Mahasiswa (BEM) Fakultas Kedokteran Gigi Universitas Indonesia. Setelah lulus dan mendapatkan gelar dokter gigi spesialis, beliau tercatat sebagai anggota PDGI Jaksel dan IKORTI KOMDA JAYA.\\n\\nTidak hanya aktif berorganisasi, drg. Efrina juga memiliki prestasi yang membanggakan, diantaranya adalah lulus dengan predikat Cum Laude, peraih IPK tertinggi wisuda program profesi tahun 2011 dan Juara 1 Dentsmart Competition pada tahun 2009.  Selain itu beliau juga tertarik dalam kegiatan sosial, aktif dalam komunitas pendidikan dan kesehatan, serta rutin menjalani pelatihan dan seminar baik dalam negeri dan luar negeri.\",\"img\":\"/uploads/a51dc2652bf41629aed3e082550433b3.jpg\",\"imgpos\":\"41% 22%\",\"active\":true,\"ord\":\"8\"}'),
(27, 'doctors', 'mv4qj1cz', '{\"name\":\"Drg. Isya Hanin, Sp. Pros\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Pembuatan Gigi Palsu\",\"degree\":\"S1 Profesi Kedokteran Gigi FKG UI (2007) dan S2 Spesialis Prostondosia FKG UI (2012)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 16 tahun\",\"sched\":\"Selasa 16:00 - 20:00 & Sabtu 08:00 - 13:00\",\"bio\":\"Dokter gigi yang biasa disapa drg. Hanin ini merupakan lulusan Program Pendidikan Profesi Kedokteran Gigi, Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2007. Lulus dari FKG UI, beliau mengabdi sebagai dokter gigi dengan mengikuti program Pegawai Tidak Tetap (PTT) di Tomohon, Sulawesi Utara selama satu tahun. Setelah PTT, drg. Hanin melanjutkan studinya di universitas yang sama dengan program studi Pendidikan Kedokteran Gigi Spesialis Prostodonsia dan lulus pada tahun 2012.\\n\\ndrg. Hanin merupakan dokter Gigi Spesialis Prostodonsia dengan pengalaman lebih dari 16 tahun dalam mendiagnosis, merencanakan, dan menangani kasus gigi kompleks yang membutuhkan perawatan prostetik. drg. Hanin memiliki keahlian dalam perancangan serta pembuatan protesa gigi untuk membantu mengembalikan fungsi dan estetika rongga mulut pasien.\\n\\nSaat ini, selain menjadi Spesialis Prostodonsia di Klinik Palapa Dentists, drg. Hanin juga menjadi menjadi staf pengajar di Departemen Prostodonti Universitas Trisakti yang turut terlibat dalam kegiatan akademik, penelitian klinis, dan pembimbingan mahasiswa. drg. Hanin juga aktif dalam kegiatan Ikatan Prostodonsia Indonesia (IPROSI).\\n\\n\",\"img\":\"/uploads/b5d6fef9526dcbe6c018fa3426d4bc66.jpg\",\"imgpos\":\"50% 31%\",\"active\":true,\"ord\":\"3\"}'),
(28, 'doctors', 'mv4qp16k', '{\"name\":\"Drg. Isma Tria Savitri, Sp. BM\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"spec\":\"Bedah Mulut\",\"degree\":\"S1 Kedokteran Gigi, FKG UI (2001-2007) dan S2 Spesialis Bedah Mulut dan Maksilofasial, FKG UI (2015)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 18 tahun\",\"sched\":\"Senin & Kamis 16:00 - 20:00\",\"bio\":\"drg. Isma Tria Savitri memulai Pendidikan Dokter Gigi di Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2001 dan lulus pada tahun 2007. Lulus dari FKG UI, ia menjalani PTT di Kabupaten Seram, Bagian Barat, Provinsi Maluku. Dokter yang pernah tergabung dalam program pertukaran pelajar di negara Swiss ini kemudian melanjutkan studinya di bidang Pendidikan Spesialis Bedah Mulut dan Maksilofasial di Fakultas Kedokteran Gigi (UI) dan lulus pada tahun 2015. Saat ini drg. Isma aktif sebagai Dokter Gigi Bedah Mulut di Palapa.\\n\\nBeliau juga aktif mengikuti berbagai kegiatan seminar, dan pelatihan profesional di bidang bedah mulut dan maksilofasial, di antaranya Kongres Nasional PABMI dan CEOMS IV (2017), Pertemuan Ilmiah Tahunan PABMI (2016) seminar “Continuing Dental Education for Professional Dentists in the Era of ASEAN Economic Community” (2016), AOCMF Course – Prinsip-prinsip Manajemen Fraktur Kraniomaksillofasial (2015)\",\"img\":\"/uploads/88661ca89308a4bb11a15cd535ee93c7.jpg\",\"imgpos\":\"50% 23%\",\"active\":true,\"ord\":\"2\"}'),
(29, 'doctors', 'mv4qwpba', '{\"name\":\"Drg. Irma Aryani, Sp. Ort\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"spec\":\"Spesialis Ortodonsia\",\"degree\":\"S1 Profesi Kedokteran Gigi FKG Universitas Prof. Dr. Moestopo (2000-2005) dan S2 Spesialis Ortodonsia FKG UI (2008-2012)\",\"experience\":\"Invisalign provider training course yang diselengggarakan oleh Align technology (2017), The Asian Damon forum bangkok yang diselenggarakan oleh Ormco (2017)\",\"sched\":\"Jumat 10:00 - 14:00 , Sabtu 15:00 - 20:00 & Minggu 09:00 - 13:00\",\"bio\":\"drg. Irma menyelesaikan pendidikan Kedokteran Gigi Spesialis Ortodonsia di Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2012. Memiliki motto, “beauty is symmetri”. drg. Irma mempunyai passion yang besar dalam memperbaiki susunan gigi geligi. Harapannya, pasien mendapatkan senyum indah dalam simetri wajah yang sempurna. Ketertarikannya terhadap dunia Orthodonsia dibuktikan melalui prestasinya sebagai Juara 1 Best Research pada 8th FDI-IDA Joint Meeting pada tahun 2012.\\n\\npada tahun 2017 drg. Irma tercatat sebagai Invisalign Provider, yaitu Spesialis Ortodonsia yang memiliki lisensi resmi dalam melakukan pemasangan Invisalign yang diselenggarakan Align Technology, Amerika Serikat. drg. Irma juga merupakan Spesialis Ortodonsia di Palapa Dentists yang telah terlatih dalam melakukan pemasangan Insignia Braces, yaitu bracket yang disesuaikan dengan kondisi gigi pasien yang menggunakan teknologi 3D dalam pemasangannya. Saat ini, drg. Irma aktif sebagai Spesialis Ortodonsia di Palapa Dentists dan selain aktif mengikuti berbagai seminar terkait Ortodonsia.\",\"img\":\"/uploads/e444b74bd41468d5bf1b1c024dfb7385.jpg\",\"imgpos\":\"50% 21%\",\"active\":true,\"ord\":\"10\"}'),
(30, 'doctors', 'mv4ws6s6', '{\"name\":\"Drg. Zatira Avriyanti\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Pendidikan Dokter Gigi FKG Unpad (2015-2019), Pendidikan Profesi Dokter Gigi FKG Unpad (2015-2021)\",\"experience\":\"Asisten Peneliti Pusat Studi Biomaterial UNPAD (2019)\",\"sched\":\"Minggu 16:00 - 20:00\",\"bio\":\"drg. Zatira Avriyanti merupakan lulusan Pendidikan Dokter Gigi Universitas Padjadjaran pada tahun 2021. Beliau mendapatkan penghargaan sebagai lulusan terbaik program sarjana kedokteran gigi & Profesi kedokteran gigi FKG Unpad pada tahun 2019 dan 2021. Selama menjalani pendidikan, drg. Zatira Avriyanti aktif dalam kegiatan akademis maupun non akademis. Salah satunya menjadi Oral Speaker pada 18th Asian Bioceramic Symposium membawakan topik mengenai penelitian tentang Bone Cement.\\n\\nSetelah mendapat gelar dokter gigi, drg. Zatira Avriyanti aktif mengikuti berbagai kegiatan seminar untuk mengembangkan keterampilan dan pengetahuan kedokteran gigi terkini. Saat ini drg. Zatira Avriyanti aktif Praktik sebagai dokter gigi umum di Palapa Dentists, MHDC Wisma BNI 46, dan Medikids Pondok Indah.\",\"img\":\"/uploads/b59a9eb08973b06585bfeb6562f06aca.jpg\",\"imgpos\":\"50% 25%\",\"active\":true,\"ord\":\"29\"}'),
(31, 'doctors', 'mv4x2sv1', '{\"name\":\"Drg. Annisa Rizki Amalia, Sp. KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Perawatan Gigi Anak\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2012) dan S2 Spesialis Kedokteran Gigi Anak FKG UI (2014 – 2017)\",\"experience\":\"Penulis buku anak : \\\"Sikat Gigi, Yuk!\\\" tentang kesehatan dan kebersihan gigi\",\"sched\":\"Rabu 09:00 - 12:30 & Minggu 09:00 - 14:00\",\"bio\":\"Dokter gigi yang akrab disapa drg. Icha menyelesaikan pendidikan S1 Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2012 dengan predikat Cumlaude setelah menempuh pendidikan selama lima tahun. Keinginan besar drg. Icha untuk menciptakan pengalaman perawatan gigi yang nyaman, menyenangkan, dan bersahabat bagi anak-anak. Hal tersebut menjadi alasan kuat baginya untuk mengambil Studi Spesialis Kedokteran Gigi Anak pada 2014-2017, dan lulus dengan IPK yang excellent\\n\\nSaat ini, drg. Icha aktif memberikan edukasi kesehatan gigi dan mulut kepada orang tua melalui media sosial Instagram @annisaramalia dan @senyumsikecil, serta aktif menjadi pembicara dalam berbagai kelas edukasi orang tua bersama @KlinikKecil. Dengan gaya komunikasi yang hangat, ringan, dan mudah dipahami, drg. Icha berupaya membantu keluarga Indonesia memahami pentingnya kesehatan gigi dan mulut anak sejak dini.\\n\\nSelain berfokus pada perawatan dan pencegahan kesehatan gigi anak, drg. Icha juga mendalami bidang airway dentistry dan myofunctional therapy pada anak untuk mendukung tumbuh kembang, kualitas napas, fungsi oral, serta kesehatan anak secara menyeluruh. Sebagai Dokter Gigi Spesialis Anak, drg. Icha dikenal memiliki pendekatan empatik dan komunikatif dalam membangun kenyamanan pasien anak selama perawatan, sehingga anak dapat menjalani perawatan gigi dengan rasa aman dan pengalaman yang positif.\",\"img\":\"/uploads/6b2eab5d575e64aa2e68c5bc0511f8fb.jpg\",\"imgpos\":\"50% 27%\",\"active\":true,\"ord\":\"9\"}'),
(32, 'doctors', 'mv4x7i97', '{\"name\":\"Drg. Indira Larasputri, M.Kes.Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Dokter Gigi Spesialis Konservasi Gigi\",\"degree\":\"S1 dan Profesi Kedokteran Gigi FKG Universitas Airlangga (2010-2016); S2 Ilmu Kedokteran Gigi (2016-2018); Spesialis Konservasi Gigi FKG UI (2020-2023)\",\"experience\":\"Staf Medis KSM Gigi dan Mulut RSCM-FKUI (2017- saat ini)\",\"sched\":\"Sabtu & Minggu 15:00 - 20:00\",\"bio\":\"Dikenal dengan panggilan drg.Indira, memulai karir di dunia kedokteran gigi setelah tamat dari Universitas Airlangga tahun 2016. Beliau langsung melanjutkan pendidikan S2 Ilmu Kedokteran Gigi hingga tahun 2018.\\n\\nSelama menempuh pendidikan S2, beliau meraih penghargaan lulusan terbaik pada tahun 2018. Pada tahun 2017, beliau berkarir menjadi staf medis KSM Gigi dan Mulut RSCM-FKUI dan berkesempatan melanjutkan pendidikan di bidang Konservasi Gigi melalui beasiswa tugas belajar dari Kementerian Kesehatan. Beliau menjadi salah satu lulusan terbaik seluruh spesialis pada tahun ajaran itu dan merupakan peraih IPK tertinggi di angkatannya. Selain itu, Beliau juga meraih peringkat 2 dalam ujian kompetensi pendidikan spesialis konservasi gigi.\",\"img\":\"/uploads/09d57c4dd2b1a64417bb9c607ed6e307.jpg\",\"imgpos\":\"50% 27%\",\"active\":true,\"ord\":\"32\"}'),
(33, 'doctors', 'mv4xcphe', '{\"name\":\"Drg. Rizky Aditya Irwandi, M.Sc., Ph.D\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Profesi Dokter Gigi FKG UI (2014) dan S2 Spesialis Oral Biology, Chulalongkorn University, Thailand (2017)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 10 tahun\",\"sched\":\"Rabu, Jumat 16:00 - 20:00 & Sabtu 09:00 - 15:00\",\"bio\":\"drg. Rizky Aditya Irwandi menyelesaikan studi S1 Profesi Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Indonesia (FKG UI) pada tahun 2014. Setelah menyelesaikan pendidikan profesi, beliau melanjutkan pendidikan spesialis di bidang Oral Biology di Fakultas Kedokteran Gigi Universitas Chulalongkorn, Thailand pada tahun 2017. drg. Rizky kembali melanjutkan pendidikan untuk mengambil gelar S3 di University College London, Eastman Dental Institute, dengan bidang Periodontology dari tahun 2019.\\n\\ndrg. Rizky memiliki berbagai prestasi akademik dan penghargaan di tingkat nasional maupun internasional, di antaranya memperoleh penghargaan sebagai lulusan terbaik dengan IPK tertinggi pada program Dokter Gigi di Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2014. Lalu pada tahun 2016, beliau berhasil meraih The Winner of Unilever Hatton Divisional Award (IADR-SEA) kategori Basic Science – Senior Category dalam 94th IADR General Session and Exhibition di Seoul, Korea Selatan. terpilih sebagai perwakilan International Association for Dental Research South East Asia (IADR-SEA) Division untuk Unilever Hatton Award kategori Basic Science – Senior Category pada 95th IADR General Session and Exhibition di San Francisco, Amerika Serikat pada tahun 2017. Serta masuk kedalam Top 8 Finalist – Senior Colgate Prize pada British Society for Oral and Dental Research (BSODR) Annual Meeting di London, Inggris pada tahun 2023.\",\"img\":\"/uploads/6fda29bb2d3863f8de78031382c683f2.jpg\",\"imgpos\":\"50% 8%\",\"active\":true,\"ord\":\"33\"}'),
(34, 'doctors', 'mv4xhx5c', '{\"name\":\"Drg. Riana Napitupulu, Sp.Perio\",\"dept\":\"Jaringan Penyangga Gigi / Periodontic\",\"spec\":\"Spesialis Periodonsia\",\"degree\":\"S1 Kedokteran Gigi FKG UI (1990 - 1997) dan S2 Spesialis Periodonsia FKG UI (2001 - 2005)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 25 tahun\",\"sched\":\"Senin, Rabu 09:00 - 13:00 & Sabtu 08:00 - 14:00\",\"bio\":\"drg. Riana merupakan lulusan Program Kedokteran Gigi Fakultas Kedokteran Gigi (FKG), Universitas Indonesia (UI) pada tahun 1997. Lulus dari FKG UI, drg. Riana mengikuti PTT di Lahewa, Pulau Nias, Sumatera Utara pada tahun 1998. Setelah mengikuti PTT selama tiga tahun, Ia melanjutkan studinya di Universitas yang sama dengan program studi Pendidikan Kedokteran Gigi Spesialis Periodonsia pada tahun 2005.\\n\\nBeliau memiliki alasan tersendiri terkait ketertarikannya dengan Spesialisasi Periodonsia. Menurutnya, ilmu periodonsia masih sedikit yang mengetahui manfaatnya, padahal periodonsia merupakan cabang ilmu kedokteran gigi yang terhubung dengan semua cabang ilmu kedokteran gigi lainnya.\\n\\ndari tahun 2021-2026 drg. Riana juga masih tetap aktif mengikuti berbagai kegiatan Seminar, praktek, Workshop, dan Events yang berhubungan dengan Periodonsia. Saat ini, drg. Riana aktif praktik sebagai Dokter Spesialis Periodonsia di Palapa Dentists dan Klinik MHDC di Bekasi.\",\"img\":\"/uploads/0a9bf4a6dda3abfae48d5be7c4a83cd3.jpg\",\"imgpos\":\"50% 24%\",\"active\":true,\"ord\":\"4\"}'),
(35, 'doctors', 'mv4xm83o', '{\"name\":\"Drg. Irvina Desiyanti, Sp. KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Perawatan Gigi Anak\",\"degree\":\"S1 Kedokteran Gigi FKG UI (1998-2003) dan S2 PPDGS Kedokteran Gigi Anak FKG UI (2004-2007)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 21 tahun, Bendahara Ikatan Dokter Gigi Anak Indonesia (IDGAI)\",\"sched\":\"Jumat 16:00 - 20:00\",\"bio\":\"drg. Irvina Desiyanti, Sp. KGA atau yang sering dipanggil drg. Vina merupakan lulusan Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2003. Ia melanjutkan studinya pada Program Pendidikan Dokter Gigi Spesialis (PPDGS) Kedokteran Gigi Anak tahun 2004 dan lulus pada tahun 2007. Komitmennya sebagai dokter gigi terlihat dari beberapa prestasi yang pernah Ia ukir semasa pendidikan hingga saat ini, diantaranya menjadi Mahasiswa Berprestasi FKG UI tahun 2002, Lulusan Terbaik III FKG UI Award tahun 2003, Juara Kedua Untuk Laporan Kasus Presentasi Lisan pada Konferensi Pediatric Dentists Association of Asia tahun 2012.\\n\\nPada tahun 2016-2024, drg. Vina menjadi bendahara Ikatan Dokter Gigi Anak Indonesia (IDGAI), Pengda, DKI Jakarta. Kepeduliannya akan pertumbuhan gigi pada anak menjadi pemikiran memilih kedokteran gigi anak sebagai spesialisasinya. Menurutnya, menanamkan kebiasaan menjaga kebersihan mulut sejak dini penting dilakukan. Saat ini, drg. Vina aktif praktik sebagai Dokter Gigi Anak di Klinik Dokter Gigi Palapa, dan Medikids Cikupa.\",\"img\":\"/uploads/aff508022a036c09732c47d1280e612f.jpg\",\"imgpos\":\"50% 14%\",\"active\":true,\"ord\":\"13\"}'),
(36, 'doctors', 'mv4xqduh', '{\"name\":\"Drg. Tri Wahyudi, Sp. Ort\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"spec\":\"Spesialis Ortodonsia\",\"degree\":\"S1 Kedokteran Gigi FKG UI (1999-2004) dan S2 Spesialis Ortodonsia FKG UI (2012-2015)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 21 tahun\",\"sched\":\"Selasa 15:00 - 20:00 & Sabtu 15:00 - 20:00\",\"bio\":\"drg. Tri menjalani Pendidikan Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 1999 dan lulus dengan predikat Cumlaude pada tahun 2004. Ketertarikannya dengan dunia kedokteran gigi terlihat dari prestasi-prestasi yang pernah Ia raih, diantaranya menjadi Finalis Duta Listerine Award pada tahun 2004, Juara 1 Mahasiswa Berprestasi Tingkat FKG UI pada tahun 2003, Juara 2 Dentsply Clinicion Program tahun 2002, dan Juara 3 Mahasiswa Berprestasi Tingkat Universitas Indonesia (UI) pada tahun 2003. Lulus S1, drg. Tri melanjutkan karirnya sebagai Pegawai Negeri Sipil (PNS) di Departemen Hukum dan HAM pada tahun 2005-2015.\\n\\nPada Tahun 2013 – 2017, drg. Tri juga aktif mengikuti Rangkaian seminar yang menunjukkan komitmen dalam pengembangan kompetensi profesional di bidang Ortodonti. Partisipasi aktif dalam berbagai forum ilmiah nasional maupun internasional yang diselenggarakan oleh Ikatan Ortodontis Indonesia, Universitas Indonesia, serta Persatuan Dokter Gigi Indonesia memperlihatkan upaya berkelanjutan untuk memperbarui wawasan, keterampilan klinis, dan pemahaman terhadap perkembangan ilmu kedokteran gigi modern.\\n\\ndrg. Tri melanjutkan studi S2-nya pada Program Pendidikan Dokter Gigi Spesialis Ortodonsia di FKG UI pada tahun 2012 dan lulus dengan predikat Cumlaude pada tahun 2015. Melihat orang-orang tersenyum ceria dan manis karena giginya yang tampak rapi dan teratur menjadi salah dua alasan drg. Tri memilih spesialisasi Ortodonsia. Saat ini, drg. Tri aktif menjadi spesialis Ortodonsia di beberapa klinik di Jakarta termasuk di Palapa Dentists serta tergabung sebagai anggota Ikatan Orthodonsia (IKORTI) dan Persatuan Dokter Gigi Indonesia (PDGI).\",\"img\":\"/uploads/7410d4ecb94883eeda32d81530fd2785.jpg\",\"imgpos\":\"50% 15%\",\"active\":true,\"ord\":\"12\"}'),
(37, 'doctors', 'mv4xvhtr', '{\"name\":\"Drg. Nidia Risky Primanda, Sp. KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Spesialis Kedokteran Gigi Anak\",\"degree\":\"S1 Kedokteran Gigi Universitas Trisakti (2006-2010), Profesi Kedokteran Gigi Universitas Trisakti (2010-2012), Spesialis Kedokteran Gigi Anak Universitas Padjajaran (2019-2022)\",\"experience\":\"Asisten Dosen Ilmu Kedokteran Gigi Anak Universitas Trisakti (2014-2019)\",\"sched\":\"Kamis 10:00 - 14:00\",\"bio\":\"Dikenal dengan drg. Nidia. Gelar dokter gigi diraih pada tahun 2012 dari Fakultas Kedokteran Gigi Universitas Trisakti, kemudian pada tahun 2014 sembari bekerja sebagai dokter gigi, beliau juga menjadi asisten dosen di Departemen Kedokteran Gigi Anak Universitas Trisakti. Pada tahun 2022, beliau mendapatkan gelar Spesialis Kedokteran Gigi Anak dari Universitas Padjadjaran dengan predikat Cum Laude, dan pernah mendapatkan penghargaan sebagai finalis literature review pada ajang Seminar Nasional Ikatan Dokter Gigi Anak Indonesia.\\n\\nSejak tahun 2012, drg. Nidia aktif menjadi anggota Persatuan Dokter Gigi Indonesia, Ikatan Dokter Gigi Anak Indonesia, dan Indonesian Society of Special Care Dentistry.  drg. Nidia juga aktif mengikuti acara ilmiah baik taraf nasional maupun Internasional, serta telah mempublikasikan beberapa buku mengenai kedokteran gigi anak. Saat ini drg. Nidia berpraktik di Palapa Dentist dan MHDC Group\",\"img\":\"/uploads/24997f514dc79303c197f4140ce64ae0.jpg\",\"imgpos\":\"50% 38%\",\"active\":true,\"ord\":\"31\"}'),
(38, 'doctors', 'mv4zwl46', '{\"name\":\"Dr. Drg. Dini Asrianti, Sp. KG, SubspKE(K)\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"degree\":\"S1 Profesi Kedokteran Gigi FKG UI (1999-2005), S2 Spesialis Konservasi Gigi FKG UI (2006-2009) dan S3 Bidang Regeneratif Endodontik dengan menggunakan Platelet Rich Plasma (PRP) Exosome FKG UI (2017- 2021)\",\"experience\":\"Ka Unit Klinik Spesialis Konservasi Gigi FKG UI, RSKGM FKG UI, Ketua Program Studi Pendidikan Spesialis Konservasi Gigi FKG UI, Pengalaman praktek sebagai dokter gigi lebih dari 17 tahun\",\"sched\":\"Rabu 16:00 - 20:00 & Minggu 08:30 - 13:00\",\"bio\":\"Drg. Dini menjalani Pendidikan Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) selama 5,5 tahun dengan tepat waktu dan mendapatkan penghargaan sebagai lulusan terbaik pada tahun 2005. Tahun 2006, drg. Dini melanjutkan studi S2-nya dengan mengambil pendidikan Spesialis Ilmu Konservasi Gigi di universitas yang sama dan lulus dengan predikat Cumlaude pada tahun 2009. Ketertarikannya akan spesialisasi Konservasi Gigi berawal dari keinginannya untuk menyembuhkan sakit gigi dengan cepat dan “less pain”. Drg Dini telah berhasi menyelesaikan studi S3 di FKG UI tahun 2021, dengan penelitian dibidang Regeneratif Endodontik dengan menggunakan Platelet Rich Plasma (PRP) Exosome.\\n\\nBerpengalaman sebagai Dokter Gigi selama lebih dari 17 Tahun. Dalam praktik klinisnya, drg. Dini menangani berbagai kasus yang berkaitan dengan kerusakan jaringan gigi, infeksi pada saraf gigi, trauma dental, hingga perawatan saluran akar pada kasus-kasus dengan tingkat kompleksitas tinggi. Saat ini, drg. Dini aktif sebagai Dokter Gigi Spesialis Konservasi Gigi di Klinik Palapa Dentists dan Medikids Bintaro.\",\"img\":\"/uploads/8aae51e014a073657b4f3832408f78ce.jpg\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"11\"}'),
(39, 'doctors', 'mv50wptr', '{\"name\":\"Drg. Savedra Pratama, Sp. Pros\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Pembuatan Gigi Palsu\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2009) , S1 Profesi Dokter Gigi FKG UI (2011) dan S2 Spesialis Prostodonsia FKG UI (2016)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 15 tahun\",\"sched\":\"Senin, Selasa & Kamis 09:00 - 14:00\",\"bio\":\"Dokter gigi yang biasa di panggil drg. Save ini merupakan lulusan Program Profesi Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2011. Setelah lulus S1 Profesi, Ia melanjutkan studi S2-nya dengan memilih Prostodonsia sebagai spesialisasinya. Berawal dari keberhasilannya merawat pasien yang kehilangan seluruh giginya dengan gigi palsu pada masa Co-ass serta pasien lansia yang memerlukan perawatan gigi palsu membuat drg. Save tertarik mendalami ilmu prostodonsia.\\n\\nKetertarikannya akan prostodonsia juga dibuktikan dengan prestasi yang pernah Ia raih, yaitu menjadi 1st Winner Poster Presentation di International Indonesia Prosthodontic Meeting (IIPROM) di Solo pada tahun 2016. Saat ini, drg. Save aktif sebagai Dokter Gigi Spesialis Prostodonsia di Rumah Sakit dan Klinik di Jakarta, serta tergabung dalam organisasi Persatuan Dokter Gigi Indonesia (PDGI) cabang Tangerang dan Ikatan Prostodonsia Indonesia (IPROSI) Jaya.\\n\\nBerpengalaman sebagai dokter gigi selama lebih dari 15 tahun, dan sudah banyak menangani kasus rehabilitasi oral yang berkaitan dengan pembuatan crown, pemasangan implan, pembuatan gigi tiruan lepasan, serta perawatan kelainan sendi rahang. Sesuai dengan perkembangan Teknologi, drg. Save telah menerapkan Digital Dentistry pada beberapa kasus seperti penggunaan Intraoral Scanner dan 3D CBCT sebagai penunjang dalam memberikan perawatan yang lebih baik dan lebih nyaman bagi pasien.\",\"img\":\"/uploads/9828c35b717985f8b82ba7985e35f671.jpg\",\"imgpos\":\"50% 15%\",\"active\":true,\"ord\":\"16\"}'),
(40, 'doctors', 'mv510zyc', '{\"name\":\"Drg. Dewi Isroyati Sugiana, Sp. KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"degree\":\"S1 Profesi Kedokteran Gigi FKG UI (2007 – 2012) dan S2 Spesialis Konservasi Gigi FKG UI (2015 – 2018)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 12 tahun\",\"sched\":\"Selasa 15:00 - 20:00 & Jumat 09:00 - 14:00\",\"bio\":\"drg. Dewi menyelesaikan studi S1 Profesi Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) pada tahun 2012. Selesai S1, Ia melanjutkan studi S2 pada bidang Spesialis Konservasi Gigi pada Januari 2018 dengan predikat Cumlaude. Konsistensinya dalam dunia Kedokteran Gigi dibuktikan dengan prestasi-prestasi yang pernah Ia raih, diantaranya; saat pendidikan, aktif dalam kegiatan BEM FKG UI, PSMKGI, dan Asia Pacific Dental Student Association (APDSA) di Malaysia dan Jepang; menjadi Speakers dalam Oral Presentation dalam Asian Endodontic Congress di Bali pada tahun 2016; Poster Presentation dalam International World Dental Research (IWDR) di Bali tahun 2018.\\n\\nTingginya kasus gigi berlubang hingga ke saraf gigi di Indonesia serta rendahnya kesadaran akan pentingnya keberlangsungan gigi membangkitkan rasa simpatik drg. Dewi akan dunia endodontik. Menurutnya, gigi yang berlubang masih dapat diatasi tanpa harus cabut dengan perawatan endodontik.\\n\\nBerpengalaman menjadi dokter gigi selama lebih dari 12 tahun. Saat ini, selain menjadi Spesialis Konservasi Gigi di Rumah Sakit dan Klinik di Jakarta, drg. Dewi aktif mengikuti berbagai seminar terkait teknologi terkini pada bidang endodontik serta estetik dentistry.\",\"img\":\"/uploads/0acea649e9c20f37b30634d03153d829.jpg\",\"imgpos\":\"50% 47%\",\"active\":true,\"ord\":\"14\"}'),
(41, 'doctors', 'mv5133b7', '{\"name\":\"Drg. Brian Vensen Lika, Sp. Pros\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Spesialis Prostodonsia\",\"degree\":\"Pendidikan Dokter Gigi Spesialis Prostodonsia Fakultas Kedokteran Gigi Universitas Indonesia (2019), Profesi Dokter Gigi Fakultas Kedokteran Gigi Universitas Indonesia (2014 - 2018), Sarjana Kedokteran Gigi Fakultas Kedokteran Gigi Fakultas Kedokteran Gigi Universitas Indonesia (2010 - 2014)\",\"experience\":\"Dosen Departemen Prostodonsia FKG UI (2024), Dokter Gigi Spesialis Prostodonsia Klinik Palapa Dentists (Sekarang)\",\"sched\":\"Rabu & Minggu 16:00 - 20:00\",\"bio\":\"drg. Brian Vensen Lika adalah seorang Dokter Gigi Spesialis Prostodonsia atau pembuatan gigi palsu.  Perjalanan akademis drg. Brian dimulai di Universitas Indonesia, dengan menyelesaikan gelar Sarjana Kedokteran Gigi (2010–2014) dan Profesi Dokter Gigi (2014–2018). Lalu drg. Brian melanjutkan pendidikan spesialis di almamater yang sama, dan berhasil menyelesaikan Pendidikan Dokter Gigi Spesialis Prostodonsia pada tahun 2024. drg. Brian juga berkontribusi dalam dunia pendidikan sebagai Dosen di Departemen Prostodonsia Fakultas Kedokteran Gigi Universitas Indonesia sejak tahun 2024.\\n\\nBerpengalaman sebagai Dokter Gigi selama Lebih dari 7 tahun. Saat ini, drg. Brian aktif sebagai Dokter Gigi Spesialis Prostodonsia di Klinik Palapa Dentists. Bidang prostodonsia menitikberatkan pada penanganan kehilangan gigi, kerusakan struktur gigi, serta perbaikan fungsi pengunyahan, bicara, dan penampilan. Dalam praktiknya, drg. Brian menangani berbagai perawatan seperti mahkota gigi, veneer, bridge, gigi tiruan lepasan maupun cekat.\",\"img\":\"/uploads/1cef548a52a1cc8582931e3c82b679a6.jpg\",\"imgpos\":\"50% 26%\",\"active\":true,\"ord\":\"34\"}'),
(42, 'doctors', 'mvan3u9o', '{\"name\":\"Drg. Sonia Margareth, Sp. Pros\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Pembuatan Gigi Palsu\",\"degree\":\"S1 Kedokteran Gigi FKG UI (2014) , dan S2 Spesialis Prostodonsia FKG UI (2018)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 12 tahun\",\"sched\":\"Senin & Jumat 15:00 - 20:00\",\"bio\":\"drg. Sonia menyelesaikan studi S1 Profesi Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Indonesia (FKG UI) pada tahun 2014 dengan predikat Cumlaude. Setelah menyelesaikan pendidikan profesi, beliau melanjutkan pendidikan spesialis di bidang Prostodonsia di Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2018.\\n\\nSelama masa pendidikan, drg. Sonia berhasil meraih berbagai prestasi akademik, di antaranya Juara 3 dalam Scientific Research Competition pada acara “39th Asia Pacific Dental Student Association” di Cairns, Australia pada tahun 2012, serta Juara 2 dalam “GSK Case Study Competition Cycle I” Fakultas Kedokteran Gigi Universitas Indonesia pada tahun yang sama.\\n\\nSelain aktif dalam bidang akademik, drg. Sonia juga rutin mengikuti berbagai seminar, webinar, dan pelatihan di bidang prostodonsia, seperti IPROSI Jaya Webinar Series Advanced Prosthodontics in New Normal Era: “Aware of Clicking and Bruxism”, New Fokus in Webinar 2020: Best Practice in Dentistry to Face The New Normal Era, Scientific Joint Meeting of Clinical Prosthodontics and Dental Materials di Yogyakarta, serta Indonesian Prosthodontic Society and Japan Prosthodontic Society Joint Meeting di Bali.\\n\\nSebagai dokter gigi spesialis prostodonsia, drg. Sonia berfokus pada perawatan penggantian gigi yang hilang, restorasi gigi dengan kerusakan berat, serta rehabilitasi fungsi dan estetika rongga mulut menggunakan bahan artifisial. Dengan pengalaman praktik lebih dari 12 tahun, saat ini drg. Sonia aktif melayani pasien di Palapa Dentists.\",\"img\":\"/uploads/b8add85b062d475f14a317a46c9d00d7.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"20\"}'),
(43, 'doctors', 'mvan7ias', '{\"name\":\"Drg. Haura Syafin\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 & Profesi Fakultas Kedokteran Gigi Universitas Indonesia (2018-2024)\",\"experience\":\"\",\"sched\":\"Jumat 09:00 - 14:00\",\"bio\":\"Drg Haura merupakan lulusan Program Sarjana Kedokteran Gigi Fakultas Kedokteran Gigi (FKG) Universitas Indonesia (UI) tahun 2021. Ia melanjutkan Program Profesi Kedokteran Gigi di Universitas Indonesia dan lulus pada tahun 2024. Baginya, dengan menjaga kesehatan gigi dan mulut sama dengan menjaga kesehatan seluruh tubuh untuk meningkatkan kualitas hidup.\\n\\nDrg. Haura memiliki pengalaman klinis yang cukup luas di berbagai fasilitas kesehatan, mulai dari RSUD hingga klinik swasta, serta rekam jejak dalam memberikan perawatan komprehensif bagi ratusan pasien setiap bulannya . Memiliki minat yang kuat dan pengalaman lebih dari 2 tahun di bidang pendidikan kesehatan, manajemen proyek kesehatan, serta pembuatan konten digital kreatif ( pembuatan konten ) untuk berbagai merek terkemuka . Drg. Haura dikenal sebagai pribadi yang pekerja keras, memiliki kemampuan komunikasi yang baik, serta berkomitmen untuk memadukan keahlian klinis dan komunikasi digital guna meningkatkan kesadaran kesehatan masyarakat .\",\"img\":\"/uploads/9a106f83e2453c5268349a7a41f3230e.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"38\"}'),
(44, 'doctors', 'mvana2pg', '{\"name\":\"Drg. Amalia Vitariyani Mukti\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 & Profesi Fakultas Kedokteran Gigi Universitas Indonesia (2018-2024)\",\"experience\":\"\",\"sched\":\"Kamis 16:00 - 20:00\",\"bio\":\"drg. Amalia Vitariyani Mukti, atau yang akrab disapa drg. Amel, merupakan lulusan Program Pendidikan Dokter Gigi Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2024. Selama masa pendidikannya, drg. Amel aktif mengembangkan kemampuan akademik dan penelitian melalui berbagai kegiatan ilmiah. drg. Amel berhasil meraih 1st Place Scientific Research Competition pada kegiatan Asia Pacific Dental Students Association Mid-Year Meeting (MYM APDSA) 2021 melalui penelitian berjudul “Application of Er:YAG Laser on the Reduction of Aerosol While Endodontic Treatment in Pandemic COVID-19 Era” . Selain itu, drg. Amel juga meraih Juara 3 pada kegiatan Dentistry Scientific Creativity & Exhibition (DSCE) melalui presentasi ilmiah bertema “Problem Based Learning: Pedodontics and Odontogenesis” .\\n\\nBerbagai pengalaman tersebut menjadi bagian dari proses pengembangan kemampuan akademik, analisis kasus, serta pemahaman di bidang kedokteran gigi. Untuk memperluas wawasan dan kompetensi profesional, drg. Amel juga aktif mengikuti berbagai seminar dan kursus kedokteran gigi, di antaranya KPPIKG ( Kursus Penyegar dan Penambah Ilmu Kedokteran Gigi ) tahun 2023. Saat ini, drg. amel aktif berpraktik di Dokter Gigi Palapa, Medikids Bintaro, dan Medikids Bekasi.\",\"img\":\"/uploads/a17900d3f12d12bb45b014e6ade17d78.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"37\"}'),
(45, 'doctors', 'mvanewbg', '{\"name\":\"Drg. Hidayatullah, Sp. KGA\",\"dept\":\"Perawatan Gigi Anak / Pedodontic\",\"spec\":\"Spesialis Kedokteran Gigi Anak\",\"degree\":\"\",\"experience\":\"\",\"sched\":\"Rabu, Kamis 16:00 - 20:00 & Minggu 15:00 - 20:00\",\"bio\":\"drg. Hidayat merupakan lulusan Program Pendidikan Dokter Gigi Universitas Sriwijaya dan telah menyelesaikan pendidikan spesialis Kedokteran Gigi Anak di Universitas Padjadjaran. Dengan latar belakang akademik serta pengalaman klinis di bidang kedokteran gigi anak, drg. Hidayat dikenal karena kemampuannya menangani berbagai kasus kesehatan gigi anak secara profesional dan penuh perhatian.\\n\\nKeahliannya meliputi pencabutan gigi dengan trauma minimal, frenektomi, operkulektomi, splinting, bedah exposure gigi, penanganan nyeri orofasial, sedasi sadar, serta perawatan periodontal dan ortodontik interseptif pada anak, termasuk penggunaan alat lepasan, fixed appliance, myobrace, dan LM activator.\\n\\nSelain itu, beliau juga memiliki pengalaman dalam menangani pasien anak dengan kebutuhan khusus dan kondisi medis tertentu, seperti HIV, penyakit jantung, serta kasus celah bibir dan langit-langit, termasuk pemasangan obturator dan feeding plate. Pendekatan yang menyeluruh dan berfokus pada kenyamanan pasien anak menjadi bagian penting dalam praktik drg. Hidayat sehari-hari.\\n\\n\",\"img\":\"/uploads/1c010f9be4f5f187a132c142f5068268.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"36\"}'),
(46, 'doctors', 'mvanjdpm', '{\"name\":\"Drg. Nurul Astrina D, Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"degree\":\"PPDGS 2018 – 2021 - Konservasi Gigi Universitas Gadjah Mada 2013 – 2015 Program Profesi Kedokteran Gigi Universitas Gadjah Mada 2009 – 2013 S1 Kedokteran Gigi Universitas Gadjah Mada\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 10 tahun\",\"sched\":\"Selasa 09:00 - 14:00\",\"bio\":\"drg. Nurul Astrina Damayanti, Sp.KG merupakan seorang dokter gigi spesialis konservasi gigi yang praktik di klinik Palapa Dentists. Dokter yang akrab disapa dengan drg. Nurul menempuh pendidikan Sarjana Kedokteran Gigi di Universitas Gadjah Mada pada tahun 2009–2013, dilanjutkan dengan Program Profesi Dokter Gigi pada tahun 2013–2015 di universitas yang sama dengan prestasi akademik yang sangat baik. Beliau kemudian melanjutkan pendidikan spesialis Program Pendidikan Dokter Gigi Spesialis (PPDGS) Konservasi Gigi di Universitas Gadjah Mada dan menyelesaikannya pada tahun 2021.\\n\\nAda yang menarik dari motivasi Dokter Nurul untuk menjadi seorang dokter gigi. Motivasinya menjadi dokter gigi spesialis konservasi gigi bermula dari pengalaman perawatan endodontik yang tidak menyenangkan. Pengalaman tersebut dijadikannya sebagai tantangan untuk memahami dunia konservasi gigi, agar bisa memberikan pengalaman yang menyenangkan dalam menjaga kesehatan gigi dan mulut bagi masyarakat.\\n\\nDalam bidang dan penelitian akademik, drg. Nurul aktif terlibat dalam kegiatan ilmiah, salah satunya melalui penelitian Program Kreativitas Mahasiswa-Penelitian (PKM-P) DIKTI tahun 2012 mengenai pemanfaatan buah mahkota dewa sebagai bahan dasar obat kumur untuk menghambat perlekatan Streptococcus mitis pada biofilm permukaan gigi secara in vitro . Beliau juga memiliki publikasi ilmiah pada Journal of Dentistry Indonesia tahun 2020 dengan judul “Conservative Management of a Maxillary Lateral Incisor with an Apical Third Root Perforation: A Case Report.” Selain aktif dalam penelitian dan publikasi, drg. Nurul juga rutin mengikuti berbagai seminar dan pelatihan ilmiah di bidang konservasi gigi dan endodontik, seperti Temu Ilmiah Nasional IKORGI V 2021 , CBCT 3D in Dentistry: Know and Use – Hands On , serta Expert Talk 2021 yang membahas perkembangan teknologi dalam dunia kedokteran gigi.\\n\\nDengan kompetensi dan dedikasi yang dimiliki, drg. Nurul fokus pada perawatan konservasi gigi, khususnya perawatan saluran akar, restorasi estetika, dan perawatan gigi dengan pendekatan minimal invasif guna menjaga kesehatan serta fungsi gigi pasien secara optimal. Di balik kesuksesan dokter Nurul, beliau juga memiliki motivasi yang bertekad untuk mengejar impiannya sebagai dokter, kutipan motivasi yang berbunyi “ketakutan adalah pengetahuan yang tidak lengkap”.\",\"img\":\"/uploads/9a477c614ef1916fb3e83073620a8a46.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"25\"}'),
(47, 'doctors', 'mvann1qu', '{\"name\":\"Drg. Waviyatul Ahdi, Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"degree\":\"S1 Kedokteran Gigi FKG UI (2012) , dan S2 Spesialis Konservasi Gigi FKG UI (2019)\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 13 tahun\",\"sched\":\"Rabu 16:00 - 20:00, Kamis 11:00 - 14:00 & Sabtu 08:30 - 14:00\",\"bio\":\"drg. Waviyatul Ahdi, Sp.KG merupakan seorang dokter gigi spesialis yang menempuh seluruh jenjang pendidikan tingginya di Universitas Indonesia. Perjalanan akademiknya dimulai dengan menempuh program S1 di Fakultas Kedokteran Gigi (FKG) Universitas Indonesia dan lulus pada tahun 2012. Beliau kemudian melanjutkan pendidikan lanjutan di almamater yang sama, dan berhasil menyelesaikan program Spesialis Konservasi Gigi di Universitas Indonesia pada tahun 2019.\\n\\ndrg. Wavi adalah seorang dokter gigi berpengalaman yang telah berpraktik sejak tahun 2013 di berbagai Rumah Sakit dan Klinik Gigi, termasuk Klinik Palapa Dentists. Memiliki spesialisasi dalam tindakan konservasi gigi, drg. Wavi sering menangani beberapa tindakan seperti perawatan saluran akar (tunggal maupun ganda) dengan berbagai kompleksitas kasus, restorasi pasca PSA (Crown dan Onlay), serta prosedur estetika seperti bleaching internal dan eksternal.\\n\\nDedikasi beliau terhadap pemutakhiran ilmu kedokteran gigi dibuktikan dengan partisipasi aktif dalam berbagai simposium internasional dan pelatihan teknis berkelanjutan di bidang endodontik dan kedokteran gigi umum.\",\"img\":\"/uploads/f8497e2b9c288c0ab2a4a9f9de1ac07b.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"26\"}'),
(48, 'doctors', 'mvant2c3', '{\"name\":\"Drg. Achmad Riwandy, Sp.Pros\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic\",\"spec\":\"Dokter Gigi Spesialis Prosthodontic\",\"degree\":\"S1 & Profesi Kedokteran Gigi FKG ULM Banjarmasin (2010-2017); S2 Spesialis Prosthodonsia FKG UI\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 9 tahun\",\"sched\":\"Senin 16:00 - 20:00, Rabu 09:00 - 14:00 & Sabtu 15:00 - 20:00\",\"bio\":\"drg. Achmad Riwandy, Sp. Pros atau lebih dikenal dengan panggilan drg. Wandy, memulai karir dan pengabdian di dunia kedokteran gigi semenjak tamat dari Universitas Lambung Mangkurat ditahun 2017. Kemudian melanjutkan kembali pendidikan spesialis di bidang Prosthodonsia FKG UI pada tahun 2020. Sangat tertarik dan mendalami bidang estetik juga rehabilitasi pada kasus-kasus kerusakan maupun pada kehilangan gigi.\\n\\ndrg. Wandy aktif mengikuti berbagai seminar, pelatihan, dan kegiatan ilmiah di bidang kedokteran gigi sebagai bentuk pengembangan kompetensi profesional, di antaranya Seminar Banjarmasin Dentistry III (2010), Seminar Kesehatan Deteksi Dini Kanker Mulut dan Pengobatannya (2013), Seminar Best in Dentistry 2 (2013), Pelatihan First Aid Advance (FAA) (2014), Seminar Continuing Professionalism Development (2015), Seminar Banjarmasin Dentistry VII (2015), Seminar “Veneer, Is It Simple?” (2016), kegiatan RISKESDAS IV oleh Kementerian Kesehatan Republik Indonesia (2018), Seminar “Diagnosis & Management of Oral and Maxillofacial Tumor” oleh Departemen Bedah Mulut dan Maksilofasial Universitas Padjadjaran (2018), Seminar “The Art of True Preparation” oleh Jun Iwata, DDS., Ph.D. (2019), serta Indonesian Symposium of Implant Dentistry 6 (2019). Selain itu, drg. Wandy juga rutin mengikuti Seminar Iprosi (Seminar khusus dalam bidang Prostodonsia) yang diadakan tiap tahun.\\n\\nBerbagai kegiatan tersebut menjadi bagian dari upaya berkelanjutan dalam memperluas wawasan dan meningkatkan kualitas pelayanan di bidang kedokteran gigi. Berpengalaman sebagai dokter gigi selama lebih dari 9 tahun. Saat ini, drg. Wandy aktif berpraktik di Palapa Dentists dan Medikids Wakaf Depok (Pesona Square Depok) sebagai dokter gigi tetap.\",\"img\":\"/uploads/372522ae95f05fc4e172144cfb006add.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"30\"}'),
(49, 'doctors', 'mvanzt98', '{\"name\":\"Drg. Chininta Oktora Aman\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 & Profesi Fakultas Kedokteran Gigi Universitas Airlangga (2016-2022), Eastman Dental Institute University College London\",\"experience\":\"\",\"sched\":\"Senin - Kamis 09:00 - 15:00\",\"bio\":\"drg. Chininta Oktora Aman atau yang biasa disapa drg. Chininta adalah dokter gigi umum yang memiliki pengalaman internasional serta pelatihan khusus dalam perawatan pasien dewasa berkebutuhan khusus ( Special Care Dentistry ).\\n\\nDengan latar belakang praktik klinis di berbagai fasilitas kesehatan terkemuka di Indonesia dan Inggris, termasuk pengalaman islami di University College London NHS Foundation Trust . drg. Chininta fokus pada penanganan pasien dengan kondisi medis kompleks, kebutuhan psikologis khusus, serta kecemasan berlebih terhadap perawatan gigi.\\n\\ndrg. Chininta selalu mengedepankan pendekatan yang komunikatif, empatik, dan berpusat pada pasien (patient -centered care ) serta berkolaborasi secara multidisiplin untuk memastikan setiap pasien mendapatkan kenyamanan maksimal dan hasil perawatan terbaik.\",\"img\":\"/uploads/e8b61ec7d81c15d8e7810a776b535909.png\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"39\"}');
INSERT INTO `docs` (`rid`, `col`, `id`, `data`) VALUES
(50, 'doctors', 'mvaovy7z', '{\"name\":\"Drg. Tantri Widyarani\",\"dept\":\"Perawatan Gigi Umum / General Practicioner Dentists\",\"spec\":\"Dokter Gigi Umum\",\"degree\":\"S1 Kedokteran Gigi Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2008\",\"experience\":\"Pengalaman praktek sebagai dokter gigi lebih dari 18 tahun\",\"sched\":\"Senin 09:00 - 14:00, Selasa 11:00 - 15:00, Rabu 16:00 - 20:00 & Kamis 10:00 - 14:00\",\"bio\":\"drg. Tantri Widyarani Menyelesaikan pendidikan Sarjana Kedokteran Gigi di Fakultas Kedokteran Gigi Universitas Indonesia (FKG UI) pada tahun 2006, kemudian melanjutkan pendidikan Profesi Dokter Gigi (KOAS) di universitas yang sama dan lulus pada tahun 2008.  drg. Tantri Memiliki ketertarikan dalam dunia kedokteran gigi dengan pendekatan pelayanan yang profesional, komunikatif, dan berorientasi pada kenyamanan pasien.\\n\\nKomitmennya sebagai dokter gigi terlihat dari beberapa prestasi yang pernah Ia raih, yaitu, menjadi salah satu dari dua orang yang terpilih oleh drg. Bambang Nursasongko, Sp. KG (K) atas tumpatan/tambalan Resin Komposit kelas II dengan anatomi dan estetika terbaik dalam workshop “Mencegah Impaksi Makanan dan Kebocoran Tepi pada Restorasi Komposit Kelas II dengan Teknik Sandwich dan Sectional Matrix” yang disponsori oleh 3M ESPE, PT. 3M Indonesia pada tanggal 09 Juli 2009 di FKG UI.\\n\\ndrg. Tantri Dokter gigi profesional dan berpengalaman selama lebih dari 18 tahun di bidang kedokteran gigi umum. Menangani pasien anak dan dewasa, ahli di bidang penambalan gigi estetik dan perawatan saluran akar gigi (syaraf) yang detail dalam setiap pekerjaannya. Saat ini, drg. Tantri aktif sebagai Dokter Gigi Umum di Palapa Dentists. drg. Tantri juga sangat senang menangani pasien anak, sehingga beliau dipercaya menjadi Dokter Gigi Penyuluh dan Pemeriksa Kesehatan Gigi Anak untuk TK Baitussalam yang telah bekerja sama dengan Palapa Dentists sejak tahun 2009. Selain aktif dalam praktik kedokteran gigi, beliau juga memiliki hobi bernyanyi sebagai salah satu bentuk penyaluran kreativitas dan keseimbangan dalam kehidupan sehari-hari.\",\"img\":\"/uploads/47b669c33e8a8a311c8326bf32fa575a.jpg\",\"imgpos\":\"50% 50%\",\"active\":true,\"ord\":\"6\"}'),
(236, 'doctors', 'mw05jhdh', '{\"name\":\"Drg. Benazir Amriza Dini, Sp. Ortho\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"spec\":\"Spesialis Ortodonsia\",\"degree\":\"S1 Kedokteran Gigi FKG Universitas Padjajaran (2013-2017), S1 Profesi Dokter Gigi FKG Universitas Padjajaran (2017-2020) dan S2 Spesialis Ortodonti FKG UI (2021-2025)\",\"experience\":\"\",\"sched\":\"Selasa 09:00 - 14:00, Kamis 09:00 - 11:00 & Minggu 15:00 - 20:00\",\"bio\":\"drg. Benazir Amriza Dini merupakan dokter gigi spesialis ortodonti lulusan Fakultas Kedokteran Gigi Universitas Indonesia. Beliau memiliki pengalaman klinis sejak 2020 di berbagai klinik gigi di Jakarta dan saat ini beliau aktif praktik sebagai dokter gigi spesialis ortodonti di Palapa Dentists.\\n\\nLatar belakang akademis drg. Benazir dimulai dari program sarjana dan profesi dokter gigi di Universitas Padjadjaran pada tahun 2013 dan selesai pada tahun 2020. drg. Benazir juga berhasil masuk sebagai 10 Besar Mahasiswa Berprestasi Universitas Padjadjaran dan meraih Juara 2 Olimpiade Radiologi Kedokteran Gigi Indonesia pada tahun 2017. Kemudian ia melanjutkan pendidikan spesialis ortodonti di Fakultas Kedokteran Gigi Universitas Indonesia pada tahun 2021 dan berhasil menyelesaikan pendidikan pada tahun 2025. \\n\\nSelain berpraktik secara klinis, drg. Benazir memiliki rekam jejak kepemimpinan dan keorganisasian yang aktif sejak masa kuliah hingga residensi, antara lain pernah menjabat sebagai Ketua BEM FKG Unpad (2017), pengurus aktif di PSMKGI , serta dipercaya sebagai Ketua Acara Bakti Sosial & Gathering Ortodonti UI 2024 . Komitmen beliau terhadap pengembangan ilmu ortodonsi terus diperbarui melalui partisipasi aktif dalam berbagai seminar, kongres nasional maupun internasional, seperti pertemuan ilmiah Ikatan Ortodontis Indonesia (IKORTI) serta forum ilmiah global lainnya .\\n\\n\",\"img\":\"/uploads/73ed89123e66ccb16ae71681a9ab1bc7.png\",\"imgpos\":\"50% 50%\",\"ord\":\"40\",\"active\":true}'),
(13, 'doctors', 's1', '{\"name\":\"Dr. drg. Anggraeni, Sp.KG\",\"dept\":\"Konservasi Gigi / Endodontic\",\"spec\":\"Spesialis Konservasi Gigi \",\"sched\":\"Senin & Kamis 09.00–13.00\",\"bio\":\"Dikenal dengan panggilan drg.Rani, memulai karirnya di dunia kedokteran gigi setelah tamat dari Universitas Indonesia tahun 1999 dengan melanjutkan pendidikan Spesialis Konservasi Gigi.\\n\\nSelama menempuh pendidikan beliau merupakan peraih penghargaan sebagai Mahasiswa Berprestasi Utama UI tahun 1998 dan 1999, serta meraih prestasi sebagai pemenang Case Report Award di dua ajang kompetisi. Sebagai komitmen dalam menerapkan ilmu spesialistik ini, beliau bekerja sebagai Dosen di Departemen Ilmu Konservasi FKG UI selama 8 tahun dan lulus program doktor (S3) pada tahun 2007 dengan predikat cumlaude. drg. Rani merupakan doktor termuda dan lulusan terbaik pada tahun ajaran itu.\\n\\nSelain menjadi spesialis, drg. Rani tergabung dalam MHDC Group Holding Company, yang terus melakukan pengembangan klinik hingga 10 cabang dengan memegang lisensi brand MHDC Clinic dan Medikids. Sampai saat ini, drg. Rani aktif dalam berbagai kegiatan seminar sebagai peserta dan pembicara baik dalam negeri maupun luar negeri.\",\"active\":true,\"degree\":\"S1 & Profesi Kedokteran Gigi FKG UI (1994-­1999); S2 Spesialis Konservasi Gigi FKG UI (2000-­2003); S3 Program Doktor Konservasi Gigi FKG UI (2001-2007)\",\"experience\":\"Dosen di Departemen Ilmu Konservasi FKG UI selama 8 tahun\",\"img\":\"/uploads/cfa0094e98ad77f2560451bcf06b2651.jpg\",\"imgpos\":\"50% 5%\",\"ord\":\"1\"}'),
(249, 'equipment', 'mw24j3kr', '{\"name\":\"Dental X-Ray\",\"dept\":\"Radiologi Gigi / Dental Radiology\",\"desc\":\"Dental X-ray biasa (intraoral) berfungsi mengambil gambaran detail dari 1–3 gigi spesifik dari dalam mulut. Manfaatnya bagi pasien adalah memberikan pencitraan yang sangat jelas dan akurat untuk mendeteksi lubang gigi di sela-sela kecil, melihat infeksi akar gigi, serta memeriksa kondisi tulang pendukung pada kasus perawatan saluran akar atau gigi goyang.\",\"img\":\"/uploads/6faa96298c4c0b07fc79f555b95a5db7.jpg\",\"imgpos\":\"50% 50%\",\"ord\":\"1\"}'),
(250, 'equipment', 'mw25ivx0', '{\"name\":\"Panoramic X-Ray Orthopos\",\"dept\":\"Radiologi Gigi / Dental Radiology\",\"desc\":\"Mesin Rontgen panoramik Orthopos berfungsi memeta seluruh struktur rongga mulut, meliputi rahang, seluruh deretan gigi, dan sendi TMJ, secara utuh dari luar mulut (ekstraoral). Pemeriksaan ini sangat bermanfaat bagi pasien karena aman, cepat, dan nyaman tanpa rasa sakit, sekaligus membantu dokter mendeteksi masalah kompleks tersembunyi seperti gigi bungsu terimpaksi, kista, hingga kelainan rahang guna merencanakan perawatan secara presisi.\",\"img\":\"/uploads/20975196d4c780b00c2613042c98be50.jpg\",\"imgpos\":\"50% 50%\",\"ord\":\"1\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(251, 'equipment', 'mw25xll5', '{\"name\":\"Cephalometric X-Ray\",\"dept\":\"Radiologi Gigi / Dental Radiology\",\"desc\":\"Fungsi utama mesin Rontgen Cephalometric adalah mengambil foto rontgen tampak samping (lateral) dari struktur tengkorak, tulang rahang, dan profil jaringan lunak wajah. Manfaatnya bagi pasien adalah memberikan analisis akurat mengenai hubungan antara pertumbuhan tulang rahang atas dan bawah terhadap tengkorak kepala. Hasil pencitraan ini sangat penting bagi dokter spesialis ortodonti untuk merencanakan pemasangan kawat gigi (behel) secara presisi, memprediksi arah pertumbuhan rahang pada anak, serta merencanakan tindakan bedah koreksi rahang (orthognathic).\",\"img\":\"/uploads/d45bcaee32cee46a670ea5e5622fc054.jpg\",\"imgpos\":\"64% 0%\",\"ord\":\"1\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(252, 'equipment', 'mw267723', '{\"name\":\"Cement Spatel\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk mencampur bahan semen kedokteran gigi. Membantu menghasilkan campuran yang merata sehingga bahan dapat diaplikasikan dengan baik pada gigi pasien.\",\"img\":\"/uploads/82ff30d55767324d6dd2bc38965317d8.jpg\",\"imgpos\":\"50% 0%\",\"ord\":\"2\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\"}'),
(253, 'equipment', 'mw26a8ph', '{\"name\":\"Bite Block\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum|Radiologi Gigi / Dental Radiology\",\"desc\":\"Digunakan untuk menjaga mulut pasien tetap terbuka selama tindakan perawatan. Membantu pasien merasa lebih nyaman dan memudahkan dokter melakukan prosedur.\",\"img\":\"/uploads/a3a471b1790dc54f011987d8a1e1b26d.jpg\",\"imgpos\":\"50% 50%\",\"ord\":\"2\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\"}'),
(254, 'equipment', 'mw4knztf', '{\"name\":\"Diagnostic Set\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membentuk dan mengaplikasikan bahan komposit pada gigi. Membantu menghasilkan tambalan yang sesuai dengan bentuk dan anatomi gigi pasien.\",\"img\":\"/uploads/9dca92be306f6ea56ccde2bd6fd46df1.jpg\",\"imgpos\":\"40% 0%\",\"ord\":\"2\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(255, 'equipment', 'mw4kqegw', '{\"name\":\"Dental Bur Carbon Steel\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk memotong, membentuk, atau menghilangkan jaringan gigi yang mengalami kerusakan. Membantu dokter mempersiapkan gigi sebelum dilakukan penambalan atau perawatan lainnya.\",\"img\":\"/uploads/9341600825ada8685c2e6a2f436e50cc.jpg\",\"imgpos\":\"36% 0%\",\"ord\":\"2\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(256, 'equipment', 'mw4ks1yg', '{\"name\":\"Dental Burnisher\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk menghaluskan dan membentuk permukaan tambalan. Membantu menghasilkan tambalan yang lebih rapi dan nyaman saat pasien menggigit.\",\"img\":\"/uploads/c415e4f400d3f3fb004c8f3613f60107.jpg\",\"imgpos\":\"50% 50%\",\"ord\":\"2\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(257, 'equipment', 'mw4l0iqu', '{\"name\":\"Dental Pinset\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk mengambil dan memegang kapas, bahan, atau benda kecil selama prosedur. Membantu menjaga ketepatan tindakan dan kebersihan area perawatan.\",\"img\":\"/uploads/2fed0cbac480de192fe920bcab172297.jpg\",\"imgpos\":\"50% 0%\",\"ord\":\"2\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\"}'),
(258, 'equipment', 'mw4l3tje', '{\"name\":\"Dental Contra Angle Handpiece \",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk menggerakkan bur dalam proses pengeboran, penghalusan, atau preparasi gigi. Membantu tindakan perawatan gigi menjadi lebih presisi dan efisien.\",\"img\":\"/uploads/c4158f2d74f974fb00b1c80c3e8d92f7.jpg\",\"imgpos\":\"50% 22%\",\"ord\":\"2\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(259, 'equipment', 'mw4l63hk', '{\"name\":\"Dental Citoject\",\"dept\":\"Konservasi Gigi / Endodontic|Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk memberikan anestesi lokal pada pasien. Membantu mengurangi rasa sakit dan meningkatkan kenyamanan selama tindakan kedokteran gigi.\",\"img\":\"/uploads/1bd13e70a7aa51ae62fda88aa4439d9f.jpg\",\"imgpos\":\"50% 45%\",\"ord\":\"2\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\"}'),
(260, 'equipment', 'mw4leogj', '{\"name\":\"Dental Satelec\",\"dept\":\"Konservasi Gigi / Endodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan sebagai perangkat ultrasonik untuk membantu tindakan pembersihan atau perawatan gigi sesuai tip yang digunakan. Membantu dokter melakukan tindakan dengan lebih efektif.\",\"img\":\"/uploads/1907e4b8bf31d669b5f241ece0f2235c.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(261, 'equipment', 'mw4lpoy5', '{\"name\":\"Dental Surgical Blade\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membuat sayatan pada jaringan lunak dalam tindakan bedah gigi. Membantu dokter melakukan prosedur bedah secara terkontrol dan presisi.\",\"img\":\"/uploads/ea48184641de03ff678dc656898fd47f.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
(262, 'equipment', 'mw4lt2yt', '{\"name\":\"Dappen Glass\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan sebagai wadah cairan tertentu selama prosedur. Membantu memudahkan penggunaan cairan dan menjaga area kerja tetap terorganisasi.\",\"img\":\"/uploads/94ebe308feef61191493c96a4febd995.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(263, 'equipment', 'mw4lvpwb', '{\"name\":\"Diagnosis Sets\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Terdiri dari alat pemeriksaan seperti kaca mulut, sonde, dan pinset. Membantu dokter mendeteksi kondisi gigi dan mulut serta menentukan kebutuhan perawatan pasien.\",\"img\":\"/uploads/73508a826aa4f191742290edb2409d2f.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(264, 'equipment', 'mw4mtux8', '{\"name\":\"Vista Scan\",\"dept\":\"Radiologi Gigi / Dental Radiology\",\"desc\":\"Membantu memposisikan image plate dengan stabil saat pengambilan radiografi. Membantu menghasilkan gambar yang lebih konsisten dan mengurangi kemungkinan pengulangan pengambilan gambar.\",\"img\":\"/uploads/e369b6bc4424b5aad43b683150fe4a4e.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"1\"}'),
(265, 'equipment', 'mw5s413a', '{\"name\":\"Excavator\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Mengangkat jaringan karies atau sisa bahan dari rongga gigi. Membantu membersihkan area sebelum dilakukan restorasi.\",\"img\":\"/uploads/2941e60bf2874066c17c4e6cf5b0f102.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(266, 'equipment', 'mw5s7rsf', '{\"name\":\"Dental Glass Plate\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menjadi media pencampuran bahan kedokteran gigi sehingga campuran lebih homogen dan mudah diaplikasikan.\",\"img\":\"/uploads/3e5aa3006b8ae59375f6e4f30b15b21a.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(267, 'equipment', 'mw5s9r41', '{\"name\":\"GIC Mixing Spatula\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Mencampur bahan Glass Ionomer Cement (GIC) agar konsisten sehingga mendukung kualitas penambalan gigi.\",\"img\":\"/uploads/d2a13b001941328d6dace747095a24ca.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(268, 'equipment', 'mw5sf3mf', '{\"name\":\"Gunting Bedah Lengkuh Ujung Tumpul\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Memotong jaringan lunak atau benang jahit dalam tindakan bedah. Bentuk lengkung membantu akses ke area tertentu.\",\"img\":\"/uploads/b82036f2f5bc76b657b9722cd02213a8.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(269, 'equipment', 'mw5si2mq', '{\"name\":\"Gunting Bedah Lurus Ujung Tajam\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Melakukan pemotongan secara presisi pada jaringan atau bahan tertentu dalam prosedur bedah.\",\"img\":\"/uploads/846b6d88f313e5b9b8e58250b5c824b9.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(270, 'equipment', 'mw5sjqmm', '{\"name\":\"Klem\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Memegang dan mengendalikan jarum jahit saat penutupan luka. Membantu proses penjahitan jaringan lebih stabil dan presisi.\",\"img\":\"/uploads/4e38cc671735dcaf1a80a0af59ab8d0c.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
