(272, 'equipment', 'mw5su1gg', '{\"name\":\"Mixing Bowl\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menampung dan mencampur bahan kedokteran gigi. Membantu persiapan bahan lebih praktis dan terkontrol.\",\"img\":\"/uploads/f2e7489f1b204e14c28aa0bef4b39c08.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(273, 'equipment', 'mw5sw2uu', '{\"name\":\"Mouth Mirror\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Membantu melihat area gigi dan mulut yang sulit dijangkau secara langsung sehingga pemeriksaan lebih menyeluruh.\",\"img\":\"/uploads/5296e7d374e5e55f9e2bc86a01423126.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
