(275, 'equipment', 'mw5t0lv2', '{\"name\":\"Omni Matrix Wingless\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Membantu membentuk dinding gigi saat penambalan, terutama gigi posterior, sehingga hasil restorasi lebih baik.\",\"img\":\"/uploads/4e82d6f8de707740091b048ec27a1b7f.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(276, 'equipment', 'mw5t2cma', '{\"name\":\"Tray Dental Instrument\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menata instrumen selama tindakan. Membantu menjaga kerapian, efisiensi, dan pengelolaan alat.\",\"img\":\"/uploads/89fc0261d6c4f4562ea3fc18cc071cb6.jpg\",\"imgpos\":\"50% 77%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
(277, 'equipment', 'mw5t4ayx', '{\"name\":\"Matrix\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Membantu membentuk dinding dan kontak antar gigi saat penambalan gigi posterior sehingga restorasi lebih sesuai anatomi.\",\"img\":\"/uploads/89209162483c1e8e1573bc53de67888c.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(278, 'equipment', 'mw5t5xgd', '{\"name\":\"Periodontal Probe\",\"dept\":\"Konservasi Gigi / Endodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Mengukur kedalaman poket periodontal untuk mengevaluasi kesehatan gusi dan mendeteksi penyakit periodontal.\",\"img\":\"/uploads/303c365c77b78fe969c55c04839a9087.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
(279, 'equipment', 'mw5t9jbz', '{\"name\":\"Plastic Filling Instrument\",\"dept\":\"Konservasi Gigi / Endodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Mengaplikasikan dan membentuk bahan tambalan agar sesuai dengan anatomi gigi sehingga hasil restorasi lebih baik.\",\"img\":\"/uploads/6952530e16be3cb3186b98a59b681494.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(280, 'equipment', 'mw5tc696', '{\"name\":\"Polishing Bur\",\"dept\":\"Meratakan Gigi / Orthodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menghaluskan dan memoles permukaan gigi atau restorasi sehingga mengurangi kekasaran dan meningkatkan kenyamanan.\",\"img\":\"/uploads/9afdf200f6ab483f914ce71248cde894.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
