(283, 'equipment', 'mw5tl8ui', '{\"name\":\"Air Polishing\",\"dept\":\"Meratakan Gigi / Orthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Membersihkan biofilm dan noda permukaan gigi menggunakan semprotan udara, air, dan serbuk khusus. Membantu meningkatkan kebersihan gigi.\",\"img\":\"/uploads/ead28df18c43b02eb50ce71ad3a615b3.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(284, 'equipment', 'mw5tnqll', '{\"name\":\"Explorer\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Memeriksa permukaan gigi dan mendeteksi kelainan tertentu sehingga membantu pemeriksaan klinis lebih teliti.\",\"img\":\"/uploads/fa0d3851f3cead76dfed7cbe5743fdcc.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(285, 'equipment', 'mw5tr7cn', '{\"name\":\"Sonde Halfmoon\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Membantu pemeriksaan area gigi yang sulit dijangkau, termasuk celah dan permukaan gigi.\",\"img\":\"/uploads/a507108920af4657c2f342ce2e4ac4d4.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
