(287, 'equipment', 'mw5tymiz', '{\"name\":\"Intra Oral Digital Scanner\",\"dept\":\"Meratakan Gigi / Orthodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Memindai kondisi gigi dan mulut secara digital untuk menghasilkan model 3D. Membantu pembuatan aligner, gigi tiruan, dan perencanaan perawatan.\",\"img\":\"/uploads/e51d5915d6be72df9478c15a19d9617d.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
