(291, 'equipment', 'mw5uahpb', '{\"name\":\"Gelas Kumur\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menampung air untuk berkumur selama atau setelah tindakan. Membantu pasien membersihkan rongga mulut dan meningkatkan kenyamanan.\",\"img\":\"/uploads/4c36f43d5a2a4b6c34c0ad6317b51834.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
