(295, 'equipment', 'mw5upgqc', '{\"name\":\"Matriks Universal\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menjadi pembatas sementara saat penambalan gigi untuk membantu membentuk dinding restorasi dan kontak antar gigi.\",\"img\":\"/uploads/98433397209ef1e700c943f30294f6f4.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(296, 'equipment', 'mw5uq9ts', '{\"name\":\"Nier Bekken\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menampung instrumen, kapas, atau limbah medis tertentu selama tindakan. Membantu menjaga area kerja lebih rapi.\",\"img\":\"/uploads/ec6ccfa9bc9396cdf42b1fc3b35df344.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
(297, 'equipment', 'mw5ur52d', '{\"name\":\"Polibib Dental\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Melindungi pakaian pasien dari air, saliva, atau bahan perawatan sehingga pasien tetap nyaman dan bersih.\",\"img\":\"/uploads/c54909e660a5500856b080e421f51890.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
(298, 'equipment', 'mw5ursn3', '{\"name\":\"Saliva Ejector\",\"dept\":\"Konservasi Gigi / Endodontic|Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic|Jaringan Penyangga Gigi / Periodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Menyedot saliva dan cairan dari rongga mulut. Membantu menjaga area kerja tetap kering dan meningkatkan kenyamanan pasien.\",\"img\":\"/uploads/42ba90a33d535f2603ab763a775eb5ff.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"2\"}'),
(299, 'equipment', 'mw5usgyg', '{\"name\":\"Safety Goggles\",\"dept\":\"— Semua departemen —\",\"desc\":\"Melindungi mata dari percikan cairan, debris, atau partikel selama tindakan sehingga meningkatkan keamanan pasien dan tenaga medis.\",\"img\":\"/uploads/18d50dcf9274249e5995a0bd466121a2.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"2\"}'),
