(301, 'equipment', 'mw6047by', '{\"name\":\"Hand Use\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membersihkan, membentuk, dan mempersiapkan saluran akar. Membantu menghilangkan jaringan pulpa yang terinfeksi serta mendukung keberhasilan perawatan saluran akar.\",\"img\":\"/uploads/e5e51da8c1cd31f4010f103717364fd7.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(302, 'equipment', 'mw606ctl', '{\"name\":\"Rotary\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membentuk dan membersihkan saluran akar menggunakan sistem instrumen endodontik. Membantu menghasilkan preparasi saluran akar yang sesuai untuk proses pengisian.\",\"img\":\"/uploads/028c6b2215265375ba9b277b90bef3da.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(303, 'equipment', 'mw607dn2', '{\"name\":\"Gutta Cutter\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk memotong bahan gutta-percha setelah pengisian saluran akar. Membantu menghasilkan pengisian yang rapi dan sesuai kebutuhan perawatan.\",\"img\":\"/uploads/52ceeee08fb72b1dc3b8d994ff4675a0.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(304, 'equipment', 'mw6087ui', '{\"name\":\"Rubber Dam Set\",\"dept\":\"Konservasi Gigi / Endodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk mengisolasi gigi dari saliva selama perawatan. Membantu menjaga area kerja tetap kering, mengurangi kontaminasi, dan meningkatkan kenyamanan serta keamanan pasien.\",\"img\":\"/uploads/a5635ae2e41167e566c0e5e609d60ee5.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(305, 'equipment', 'mw609be5', '{\"name\":\"Bone File\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"desc\":\"Digunakan untuk menghaluskan permukaan tulang setelah tindakan bedah. Membantu mengurangi ketidakteraturan tulang dan mendukung proses penyembuhan.\",\"img\":\"/uploads/755c3ff728c87d4f823f65de980d8910.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(306, 'equipment', 'mw60azpb', '{\"name\":\"Elevator Dental\",\"dept\":\"Bedah Mulut / Oral Surgery|Perawatan Gigi Anak / Pedodontic\",\"desc\":\"Digunakan untuk membantu melonggarkan gigi dari jaringan pendukung sebelum pencabutan. Membantu proses ekstraksi gigi lebih terkontrol.\",\"img\":\"/uploads/2b269a682d234f1e2d586307de7f2788.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(307, 'equipment', 'mw60ccjx', '{\"name\":\"Extraction Forcep Crown\",\"dept\":\"Bedah Mulut / Oral Surgery|Perawatan Gigi Anak / Pedodontic\",\"desc\":\"Digunakan untuk mencabut gigi dewasa maupun gigi anak. Membantu dokter melakukan ekstraksi sesuai bentuk dan kondisi gigi pasien.\",\"img\":\"/uploads/b16d8d5d2da4aca847dd3f6f8cba3c82.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(308, 'equipment', 'mw60dkps', '{\"name\":\"Luxating Elevator\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"desc\":\"Digunakan untuk memisahkan ligamen periodontal dan membantu melonggarkan gigi sebelum pencabutan. Mendukung ekstraksi yang lebih terkontrol.\",\"img\":\"/uploads/efe401abc14e08447211029a37edac96.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(309, 'equipment', 'mw60ejzo', '{\"name\":\"Needle Holder\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan untuk memegang dan mengendalikan jarum jahit saat penutupan luka. Membantu proses penjahitan jaringan secara stabil dan presisi.\",\"img\":\"/uploads/8dbbe31aa995453d2be3555ea6b49717.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(310, 'equipment', 'mw60g4m0', '{\"name\":\"Implan Kit\",\"dept\":\"Bedah Mulut / Oral Surgery|Pembuatan Gigi Palsu / Prosthodontic\",\"desc\":\"Digunakan sebagai perangkat pendukung pemasangan implan gigi. Membantu dokter melakukan prosedur implantasi untuk mendukung penggantian gigi yang hilang.\",\"img\":\"/uploads/608073f0a2d8680370c9d4b6f5345c3a.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(311, 'equipment', 'mw60h8mn', '{\"name\":\"Raspatorium\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan untuk memisahkan atau mengangkat jaringan lunak dari permukaan tulang. Membantu dokter memperoleh akses ke area bedah dengan lebih baik.\",\"img\":\"/uploads/5b647e05a768e200163fed69e65186c5.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(312, 'equipment', 'mw60j6it', '{\"name\":\"Retractor MInnesota\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan untuk menarik dan menahan jaringan pipi, bibir, atau flap jaringan agar area bedah terlihat jelas. Membantu meningkatkan visibilitas dan keamanan tindakan.\",\"img\":\"/uploads/e2442ff452aa76e78267b36c21907a08.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(313, 'equipment', 'mw60k8vx', '{\"name\":\"Scalpel Handle\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan sebagai pegangan mata pisau bedah untuk membuat sayatan pada jaringan lunak. Membantu dokter melakukan sayatan secara presisi dan terkontrol.\",\"img\":\"/uploads/983489130a037204028219b2492fc198.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(314, 'equipment', 'mw60l3i6', '{\"name\":\"Surgical Suction Tip\",\"dept\":\"Bedah Mulut / Oral Surgery\",\"desc\":\"Digunakan untuk menyedot darah, saliva, dan cairan selama tindakan bedah. Membantu menjaga area operasi tetap terlihat dan mendukung kenyamanan pasien.\",\"img\":\"/uploads/03047ef7214f08eb6aecc24430955b32.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(315, 'equipment', 'mw60mcwr', '{\"name\":\"Scissors\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan untuk memotong jaringan lunak atau benang jahit sesuai jenis gunting. Membantu dokter melakukan tindakan bedah secara presisi.\",\"img\":\"/uploads/09cf5ea52f0b48ca99722ec24cf615b2.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(316, 'equipment', 'mw60o0u2', '{\"name\":\"Bone Dental Curette\",\"dept\":\"Bedah Mulut / Oral Surgery|Jaringan Penyangga Gigi / Periodontic\",\"desc\":\"Digunakan untuk membersihkan jaringan atau debris pada area tulang dan rongga bedah. Membantu dokter membersihkan area tindakan.\",\"img\":\"/uploads/adc8855fbf3fd69c12698da411482e1d.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(317, 'equipment', 'mw60qb1z', '{\"name\":\"Bracket Position Gauge\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk menentukan posisi pemasangan bracket pada gigi. Membantu menghasilkan posisi bracket yang lebih akurat sehingga mendukung pergerakan gigi sesuai rencana perawatan.\",\"img\":\"/uploads/06038514796835e740cbb27ea2637be8.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(318, 'equipment', 'mw60rwae', '{\"name\":\"Cheek Retractor\",\"dept\":\"Meratakan Gigi / Orthodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk menarik pipi agar area gigi terlihat lebih jelas. Membantu dokter melakukan pemasangan bracket dan pemeriksaan orthodontic.\",\"img\":\"/uploads/69a1dab47a157024bf4f6eef31ea88f1.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(319, 'equipment', 'mw60suml', '{\"name\":\"Ligature Instrument\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memasang atau mengencangkan ligature pada bracket. Membantu menjaga kawat orthodontic tetap terhubung dengan bracket.\",\"img\":\"/uploads/ad7288663cd37b1fc2ad341404c290ce.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(320, 'equipment', 'mw60toxh', '{\"name\":\"Lip Wider\",\"dept\":\"Meratakan Gigi / Orthodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membuka dan menahan bibir agar area gigi terlihat. Membantu dokter melakukan pemeriksaan dan pemasangan alat orthodontic.\",\"img\":\"/uploads/804aefe7a72c775630757911d4ac3726.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(321, 'equipment', 'mw60ui6q', '{\"name\":\"Bracket Instrument\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memegang dan menempatkan bracket pada permukaan gigi. Membantu pemasangan bracket secara presisi untuk mendukung pergerakan gigi.\",\"img\":\"/uploads/c59ccf2433ae90ced04a5addcd8610ef.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(322, 'equipment', 'mw60vgua', '{\"name\":\"Tongue Retractor\",\"dept\":\"Meratakan Gigi / Orthodontic|Bedah Mulut / Oral Surgery|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk menahan lidah agar tidak menghalangi area tindakan. Membantu meningkatkan visibilitas dan kenyamanan selama prosedur.\",\"img\":\"/uploads/cc7e8aa5a911b4b95ac437223a6bb4fe.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(323, 'equipment', 'mw60wdb7', '{\"name\":\"Wire Cutting Instrument\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memotong kawat orthodontic sesuai panjang yang diperlukan. Membantu mengurangi bagian kawat yang berlebih dan meningkatkan kenyamanan pasien.\",\"img\":\"/uploads/074252534eadb99abb8c08a3ee2c472f.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(324, 'equipment', 'mw60xc9s', '{\"name\":\"Light Wire Cutter Plier\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memotong kawat orthodontic berukuran ringan. Membantu penyesuaian kawat selama perawatan.\",\"img\":\"/uploads/3722d48dbb1e7338ae593d314cdc241c.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(325, 'equipment', 'mw60yq6c', '{\"name\":\"Weingart Plier\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memegang, memasukkan, dan mengarahkan kawat orthodontic. Membantu dokter melakukan penyesuaian kawat secara presisi.\",\"img\":\"/uploads/11e91340c7c3209188afeef7d8980cc0.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(326, 'equipment', 'mw60zoy9', '{\"name\":\"Crimpable Hook\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan sebagai hook yang dipasang pada kawat orthodontic untuk membantu pemasangan elastik atau komponen tambahan. Mendukung pergerakan gigi sesuai rencana perawatan.\",\"img\":\"/uploads/d721b5a1b1fdad6c3b2994d2356c1c17.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(327, 'equipment', 'mw610o2g', '{\"name\":\"NiTi Bending Plier\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk membengkokkan ujung kawat NiTi orthodontic sesuai kebutuhan. Membantu menyesuaikan kawat agar tidak mengganggu jaringan mulut.\",\"img\":\"/uploads/aa058b2334fc1c97a74f67a74abb510a.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(328, 'equipment', 'mw611e15', '{\"name\":\"Universal Plier\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memegang, membengkokkan, dan menyesuaikan kawat orthodontic. Membantu dokter melakukan berbagai penyesuaian alat.\",\"img\":\"/uploads/5b7447d6acc5853e530f35ebb7d43498.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(329, 'equipment', 'mw611y55', '{\"name\":\"Removal Plier\",\"dept\":\"— Semua departemen —\",\"desc\":\"Digunakan untuk membantu pelepasan komponen orthodontic tertentu. Membantu proses pelepasan alat secara terkontrol.\",\"img\":\"/uploads/dd9e7428e086699b2de8f3dc84dac6a7.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(330, 'equipment', 'mw6133yz', '{\"name\":\"Intraoral Ligature and Wire Lock\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk membantu mengunci atau mengamankan ligature dan kawat orthodontic. Mendukung kestabilan komponen selama perawatan.\",\"img\":\"/uploads/41e821e69294d43f51c6df37eee15f23.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(331, 'equipment', 'mw613zd5', '{\"name\":\"Crown Remover\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membantu melepaskan mahkota gigi tiruan yang telah terpasang. Membantu proses pelepasan restorasi untuk perbaikan atau penggantian.\",\"img\":\"/uploads/2e4f72e614f42a668fb95d65b404aaf5.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(332, 'equipment', 'mw614u8p', '{\"name\":\"Impression Tray\",\"dept\":\"Meratakan Gigi / Orthodontic|Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Anak / Pedodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan sebagai wadah bahan cetak untuk merekam bentuk gigi dan jaringan mulut. Membantu menghasilkan model yang akurat untuk pembuatan gigi tiruan, mahkota, atau alat orthodontic.\",\"img\":\"/uploads/85f80ba6b14ee81eeddc44522d20fd1d.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(333, 'equipment', 'mw615o3a', '{\"name\":\"Crown Retractor\",\"dept\":\"Pembuatan Gigi Palsu / Prosthodontic|Perawatan Gigi Umum / Dokter Gigi Umum\",\"desc\":\"Digunakan untuk membantu melepaskan atau menarik mahkota gigi tiruan sesuai jenis instrumen. Membantu proses perbaikan atau penggantian restorasi.\",\"img\":\"/uploads/b3d30218c88fc6c50ff4aeafdaf4bdbd.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(334, 'equipment', 'mw61za3q', '{\"name\":\"Bracket Tweezers\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk mengambil dan memegang bracket sebelum ditempelkan pada gigi. Membantu proses pemasangan lebih mudah dan terkontrol.\",\"img\":\"/uploads/6f813b2946043bb330138629821ff522.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(335, 'equipment', 'mw620c7a', '{\"name\":\"Orthodontic Bonding Instrument\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Membantu mengaplikasikan dan menyesuaikan bahan perekat bracket. Mendukung pemasangan bracket yang stabil.\",\"img\":\"/uploads/327d303094c1942782f495dc5e660632.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(336, 'equipment', 'mw6215cb', '{\"name\":\"Dental Etching Gel\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk mempersiapkan permukaan enamel sebelum aplikasi bonding. Membantu meningkatkan daya lekat bahan perekat bracket.\",\"img\":\"/uploads/a8f93ec8f0d77c13c54c2c354cc5b8ca.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(337, 'equipment', 'mw621v4u', '{\"name\":\"Archwire\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Kawat utama yang dipasang pada bracket untuk menghasilkan gaya pergerakan gigi. Membantu meratakan dan mengatur posisi gigi secara bertahap.\",\"img\":\"/uploads/3c5f84bde7eadd17b03e0c0b90c053be.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(338, 'equipment', 'mw622qgo', '{\"name\":\"Elastic Ligature\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk mengikat archwire pada bracket. Membantu menjaga kawat tetap berada pada slot bracket.\",\"img\":\"/uploads/02086651fa8fe325934816ea952d4783.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}');
INSERT INTO `docs` (`rid`, `col`, `id`, `data`) VALUES
(339, 'equipment', 'mw623c86', '{\"name\":\"Molar Band\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Cincin logam yang dipasang pada gigi geraham sebagai penyangga komponen orthodontic tertentu. Membantu memberikan stabilitas pada alat behel.\",\"img\":\"/uploads/2689a9ba9a35d77ce5c592246fdf46dc.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Terpotong rapi (posisi bisa diatur di atas)\",\"ord\":\"\"}'),
(340, 'equipment', 'mw623vln', '{\"name\":\"Band Seater\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk membantu menempatkan molar band pada gigi geraham. Membantu pemasangan band lebih stabil dan sesuai posisi.\",\"img\":\"/uploads/182c674b5b06d2789345a81621009266.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(341, 'equipment', 'mw624o1h', '{\"name\":\"Orthodontic Separator\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk menciptakan ruang kecil di antara gigi sebelum pemasangan molar band. Membantu proses pemasangan band lebih mudah.\",\"img\":\"/uploads/e3c440551ce10b466d71046fde635df9.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(342, 'equipment', 'mw626tym', '{\"name\":\"Elastic Placement Instrument\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan untuk memasang elastik orthodontic pada bracket atau hook. Membantu pasien dan dokter menempatkan elastik dengan tepat.\",\"img\":\"/uploads/5eea9f61b08b7e47c7410be8c321fda5.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(343, 'equipment', 'mw62foen', '{\"name\":\"Metal Bracket\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Digunakan sebagai komponen behel yang ditempelkan pada gigi untuk mengarahkan pergerakan gigi. Membantu memperbaiki susunan gigi yang tidak rata dan hubungan gigitan.\",\"img\":\"/uploads/fa322ae6eff69f4f7b2d1e4a72d2fc4d.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(344, 'equipment', 'mw62gdu8', '{\"name\":\"Clear Aligner\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Alat orthodontic transparan yang digunakan untuk menggerakkan gigi secara bertahap. Membantu memperbaiki susunan gigi dengan alat lepasan yang relatif tidak mencolok.\",\"img\":\"/uploads/0f956c51bfff044924c2efda3c12d340.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(345, 'equipment', 'mw62h2zn', '{\"name\":\"Retainer Wire\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Kawat retainer yang digunakan untuk mempertahankan posisi gigi setelah perawatan orthodontic. Membantu mengurangi risiko pergeseran gigi kembali.\",\"img\":\"/uploads/0a091f2ae4295acf5b72f7473a62a0e2.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(346, 'equipment', 'mw62j3e0', '{\"name\":\"Hawley Retainer\",\"dept\":\"Meratakan Gigi / Orthodontic\",\"desc\":\"Retainer lepasan yang terdiri dari basis akrilik dan kawat. Digunakan untuk mempertahankan posisi gigi setelah behel dilepas.\",\"img\":\"/uploads/e78fe2ed9521a39362dcddb49fc815ae.jpg\",\"imgpos\":\"50% 50%\",\"imgfit\":\"Utuh, seluruh foto terlihat (tidak dipotong)\",\"ord\":\"\"}'),
(352, 'faq', 'mw8q1jcy', '{\"q\":\"Berapa lama pemeriksaan atau perawatan berlangsung?\",\"a\":\"Durasi bergantung pada jenis pemeriksaan atau tindakan dan kondisi sahabat, jadi tiap kunjungan bisa berbeda. ⏳ Bagian pendaftaran dapat membantu memberikan perkiraan durasi sesuai kebutuhan Anda, sedangkan dokter akan menjelaskan lebih pasti setelah evaluasi. 🩺\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"10\"}'),
(353, 'faq', 'mw8q2d3z', '{\"q\":\"Apakah saya bisa memilih dokter?\",\"a\":\"Bisa disampaikan! 👩‍⚕️👨‍⚕️ Beri tahu bagian pendaftaran dokter yang ingin Anda temui. Karena ketersediaan dokter mengikuti jadwal praktiknya, janji temu perlu dibuat terlebih dahulu dan dikonfirmasi. Anda dapat melihat profil dokter di halaman Our Dentists dan jadwal praktiknya di halaman Timetable 🗓️ pada website kami.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"11\"}'),
(354, 'faq', 'mw8q9rch', '{\"q\":\"Saya belum tahu harus menemui dokter spesialis apa. Bagaimana?\",\"a\":\"Tidak apa-apa, Sahabat! 😊 Ceritakan keluhan Anda secara umum (misalnya gigi berlubang, nyeri, gusi berdarah, atau gigi berantakan) kepada bagian pendaftaran, dan mereka akan membantu mengarahkan proses konsultasi yang sesuai. Penentuan kebutuhan perawatan tetap dilakukan oleh dokter setelah pemeriksaan. 🩺 Anda juga bisa melihat daftar layanan kami di halaman Departments.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"12\"}'),
(355, 'faq', 'mw8qaxjm', '{\"q\":\"Apakah konsultasi berarti langsung dilakukan tindakan?\",\"a\":\"Belum tentu. 🙂 Dokter akan memeriksa kondisi Anda, menjelaskan temuan dan pilihan perawatan, lalu membahas langkah selanjutnya bersama Anda. Tindakan dilakukan sesuai hasil evaluasi dan persetujuan sahabat. ✅ Anda berhak bertanya sampai benar-benar paham.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"13\"}'),
(356, 'faq', 'mw8qcva0', '{\"q\":\"Apakah perlu rontgen sebelum perawatan?\",\"a\":\"Tidak semua kondisi memerlukan rontgen. 🩻 Dokter akan menentukan perlu tidaknya pemeriksaan penunjang berdasarkan pemeriksaan klinis. Jika diperlukan, Palapa Dentists memiliki layanan Radiologi Gigi, antara lain rontgen dental (periapikal), panoramic, cephalometric, dan CBCT. Dokter akan menjelaskan jenis pemeriksaan yang sesuai dan alasannya. 😊\\n\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"14\"}'),
(357, 'faq', 'mw8qdeju', '{\"q\":\"Apakah saya boleh membawa hasil rontgen dari klinik lain?\",\"a\":\"Boleh dibawa, Sahabat! 📂 Hasil rontgen sebelumnya dapat membantu dokter melihat riwayat kondisi gigi Anda. Apakah hasil tersebut dapat digunakan atau perlu pemeriksaan ulang, dokterlah yang menilai kesesuaiannya. Anda juga dapat menanyakannya lebih dulu kepada bagian pendaftaran atau dokter.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"15\"}'),
(358, 'faq', 'mw8qet2b', '{\"q\":\"Apakah klinik menyediakan resep atau obat?\",\"a\":\"Kebutuhan obat atau resep ditentukan oleh dokter setelah memeriksa kondisi Anda, sehingga disesuaikan dengan kebutuhan masing-masing sahabat. 💊 Jika dokter menilai perlu, Anda akan mendapat penjelasan mengenai obat dan aturan pemakaiannya. Untuk informasi prosedur pemberian obat di klinik, silakan tanyakan kepada bagian pendaftaran.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"16\"}'),
(359, 'faq', 'mw8qga1i', '{\"q\":\"Bagaimana jika saya memiliki alergi obat atau kondisi kesehatan tertentu?\",\"a\":\"Informasi ini sangat penting demi keselamatan Anda. 🛡️ Sampaikan kepada dokter sebelum pemeriksaan atau tindakan: alergi obat atau bahan tertentu (misalnya anestesi atau lateks), obat yang sedang dikonsumsi, serta kondisi kesehatan yang relevan seperti diabetes, tekanan darah tinggi, atau kehamilan. Mohon jangan menyembunyikan informasi tersebut, karena dokter akan menyesuaikan rencana perawatan dengan kondisi Anda. 🙏\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"17\"}'),
(360, 'faq', 'mw8qhung', '{\"q\":\"Apakah saya bisa meminta salinan hasil pemeriksaan atau rekam medis?\",\"a\":\"Bisa diajukan, mengikuti prosedur klinik. 📄 Karena menyangkut data pribadi, permintaan dokumen medis memerlukan verifikasi identitas. Silakan hubungi bagian pendaftaran untuk mengetahui syarat, proses, dan perkiraan waktu yang berlaku. 🔒\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"18\"}'),
(361, 'faq', 'mw8qiomi', '{\"q\":\"Saya mengalami sakit gigi yang berat. Apakah harus menunggu janji temu?\",\"a\":\"Sakit gigi yang berat memang sangat tidak nyaman, jangan ditahan sendiri ya. 😣 Segera hubungi klinik untuk menyampaikan keluhan dan menanyakan arahan, dan dokter yang akan menentukan penanganan yang tepat. 🚨 Segera cari pertolongan medis darurat jika Anda mengalami kesulitan bernapas atau menelan, pembengkakan yang cepat memburuk, atau kondisi yang terasa mengancam keselamatan.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"19\"}'),
(362, 'faq', 'mw8qlob3', '{\"q\":\"Apakah klnik menerima BPJS?\",\"a\":\"Daftar mitra asuransi kami dapat dilihat di halaman Insurances (Mitra Asuransi) pada website. 🏥 Untuk BPJS dan ketentuan klaim, penerimaannya bergantung pada kerja sama dan kebijakan klinik, jadi silakan konfirmasi kepada bagian pendaftaran sebelum kunjungan agar tidak ada kendala. 😊\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"20\"}'),
(363, 'faq', 'mw8v2qt4', '{\"q\":\"Apa yang perlu saya siapkan untuk kunjungan pertama?\",\"a\":\"Halo Sahabat Palapa! 👋 \\nAgar kunjungan pertama berjalan lancar, sebaiknya siapkan: \\n\\n🪪 identitas diri untuk keperluan pendaftaran \\n📝 gambaran singkat keluhan yang dirasakan dan sejak kapan\\n💊 daftar obat yang sedang dikonsumsi serta riwayat alergi atau kondisi kesehatan tertentu\\n🩻 hasil pemeriksaan atau foto rontgen gigi sebelumnya jika ada. Apakah ada dokumen lain yang perlu dibawa, silakan tanyakan kepada bagian pendaftaran. \\n\\n🪥 Oh iya, jangan lupa sikat gigi sebelum datang agar pemeriksaan terasa lebih nyaman.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"3\"}'),
(364, 'faq', 'mw8v3kcl', '{\"q\":\"Saya sahabat baru, apakah perlu mengisi formulir?\",\"a\":\"Selamat datang di keluarga Palapa Dentists! 🤗 Sahabat baru akan dibantu oleh bagian pendaftaran dalam proses registrasi, termasuk pengisian data diri dan riwayat kesehatan singkat. Formulir dan data apa saja yang perlu disiapkan dapat dikonfirmasi langsung kepada bagian pendaftaran sebelum kunjungan, supaya prosesnya di klinik lebih cepat. 📝 Anda juga bisa mulai dengan membuat janji temu melalui tombol Make an Appointment di website kami.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"4\"}'),
(365, 'faq', 'mw8v43u1', '{\"q\":\"Apakah saya perlu datang lebih awal?\",\"a\":\"Sangat dianjurkan! ⏰ Datang lebih awal dari waktu janji temu memberi ruang untuk proses administrasi dan persiapan sebelum masuk ke ruang perawatan, sehingga Anda tidak perlu terburu-buru. Berapa menit tepatnya waktu kedatangan yang disarankan, silakan tanyakan kepada bagian pendaftaran ya. 😊\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"5\"}'),
(366, 'faq', 'mw8v4r7i', '{\"q\":\"Jika saya terlambat, apakah masih bisa dilayani?\",\"a\":\"Tenang, Sahabat, jangan panik. 🙏 Segera hubungi bagian pendaftaran dan sampaikan perkiraan waktu kedatangan Anda. Pelayanan bergantung pada jadwal dokter dan kondisi antrean saat itu, sehingga bagian pendaftaran akan membantu memastikan apakah janji temu masih dapat dilayani atau perlu dijadwalkan ulang. 📅\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"6\"}'),
(367, 'faq', 'mw8v5rk8', '{\"q\":\"Bolehkah saya datang bersama pendamping?\",\"a\":\"Kenyamanan sahabat adalah prioritas kami. 💙 Kebijakan pendamping dapat bergantung pada kebutuhan sahabat dan kondisi klinik saat itu, misalnya jenis tindakan dan ruang perawatan. Agar tidak ada kendala, silakan konfirmasi kepada bagian pendaftaran sebelum kunjungan.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"7\"}'),
(368, 'faq', 'mw8vqcpi', '{\"q\":\"Metode pembayaran apa yang tersedia?\",\"a\":\"Metode pembayaran yang berlaku dapat dikonfirmasi kepada bagian pendaftaran Palapa Dentists sebelum atau saat kunjungan. 💳 Sebaiknya ditanyakan lebih dulu agar Anda bisa menyiapkannya. Perlu diketahui juga bahwa biaya perawatan pasti ditentukan setelah pemeriksaan dokter; perkiraan biayanya bisa dilihat di halaman Katalog. 📚\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"21\"}'),
(369, 'faq', 'mw8vrfyb', '{\"q\":\"Saya tidak tahu nama tindakan yang saya butuhkan. Bisa dibantu?\",\"a\":\"Bisa banget! 😊 Ceritakan saja apa yang Anda rasakan atau ingin diperbaiki, misalnya gigi sakit, gigi kuning, gusi berdarah, atau gigi berantakan, tanpa perlu tahu istilah medisnya. Bagian pendaftaran akan membantu mengarahkan proses konsultasi, dan dokter akan menentukan tindakan yang tepat setelah pemeriksaan. 🩺 Perlu diingat, asisten AI kami tidak dapat memastikan diagnosis atau menentukan tindakan tanpa pemeriksaan dokter.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"22\"}'),
(370, 'faq', 'mw8vs4zp', '{\"q\":\"Apakah sedang ada promo di Palapa Dentists?\",\"a\":\"Ada! 🎉 Salah satu promo yang sedang kami tawarkan adalah Special Bundling: Scaling + Probiotik 🦷💊, yaitu Scaling All Cases + 30 tablet probiotik dengan keterangan HEMAT 450K. Cocok untuk sahabat yang ingin membersihkan plak dan karang gigi di klinik sekaligus melanjutkan perawatan kesehatan mulut di rumah (Double Care untuk kebersihan dan kesehatan mulut ✨).\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"23\"}'),
(371, 'faq', 'mw8vtowd', '{\"q\":\"Layanan apa saja yang tersedia di Palapa Dentists?\",\"a\":\"Palapa Dentists melayani berbagai kebutuhan kesehatan gigi dan mulut untuk anak-anak hingga dewasa. 🦷 Layanan kami meliputi:\\n\\n🦷 Perawatan Gigi Umum (General): pemeriksaan gigi secara umum, misalnya konsultasi, scaling, penambalan, dan bleaching.\\n🔬 Konservasi Gigi (Endodontic): perawatan saraf dan saluran akar gigi, penambalan, crown, veneer, dan bleaching intra corona.\\n😁 Meratakan Gigi (Orthodontic): pemasangan kawat gigi/brackets, retainer, dan ortho lepasan.\\n🩺 Bedah Mulut (Oral Surgery): pembedahan di area mulut dan rahang, seperti pencabutan gigi, odontectomy, dan implan gigi.\\n👑 Pembuatan Gigi Palsu (Prosthodontic): gigi palsu pada area gigi yang tanggal, crown, bridge, dan implan gigi.\\n🌿 Jaringan Penyangga Gigi (Periodontic): perawatan gusi dan jaringan penyangga gigi, misalnya scaling, gingivektomi, dan flap operation.\\n🧒 Perawatan Gigi Anak (Pedodontic): perawatan gigi anak-anak, seperti penambalan, cabut gigi susu, dan space maintainer.\\n🩻 Radiologi Gigi (Dental Radiology): rontgen dental (periapikal), panoramic, cephalometric, TMJ, dan CBCT.\\n\\nDaftar layanan terlengkap dapat dilihat di halaman Departments dan Katalog website kami. Tindakan yang sesuai untuk Anda ditentukan dokter setelah pemeriksaan. 😊\\n\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"0\"}'),
(372, 'faq', 'mw8vuhng', '{\"q\":\"Bagaimana cara mengetahui perkiraan biaya suatu layanan?\",\"a\":\"Anda bisa melihat daftar perawatan beserta perkiraan biayanya di halaman Katalog website kami. 📚 Perlu diketahui bahwa biaya tersebut bersifat estimasi, dan biaya pastinya ditentukan setelah pemeriksaan dokter karena kondisi setiap sahabat berbeda. 💬 Untuk informasi lebih lanjut, silakan tanyakan kepada bagian pendaftaran.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"24\"}'),
(373, 'faq', 'mw8vxnw2', '{\"q\":\"Di mana saya bisa mendapatkan tips atau informasi seputar kesehatan gigi?\",\"a\":\"Kunjungi bagian Blogs di website palapadentists.com! 📖 Di sana kami menulis artikel seputar kesehatan gigi dan perawatan di klinik, misalnya \\\"Mengatasi Rasa Takut ke Dokter Gigi Melalui Konsep Homey Dental Klinik\\\". 💡 Artikel bersifat edukasi umum dan tidak menggantikan pemeriksaan dokter, jadi untuk kondisi pribadi Anda, tetap konsultasikan kepada dokter kami. 🩺\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"25\"}'),
(1, 'faq', 's1', '{\"q\":\"Jam berapa klinik buka?\",\"a\":\"Jam praktek kami: Senin–Jumat {jam_senin_jumat}, Sabtu–Minggu {jam_sabtu_minggu}. Jadwal tiap dokter dapat dilihat di halaman Timetable. Namun untuk memastikan dapat menghubungi bagian pendaftaran🕰️\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"1\"}'),
(2, 'faq', 's2', '{\"q\":\"Di mana lokasi klinik?\",\"a\":\"{alamat}. Google Maps dan Petunjuk arah dalam bentuk video tersedia di halaman Contact.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"2\"}'),
(3, 'faq', 's8', '{\"q\":\"Apakah anak boleh datang bersama orang tua?\",\"a\":\"Tentu! 👨‍👩‍👧 Anak sebaiknya didampingi orang tua atau wali saat berkunjung. Untuk si kecil, kami juga memiliki layanan Perawatan Gigi Anak (Pedodontic) 🧒 yang khusus menangani permasalahan gigi pada anak-anak. Untuk ketentuan pendaftaran dan pendampingan, silakan konfirmasi kepada bagian pendaftaran.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"8\"}'),
(4, 'faq', 's9', '{\"q\":\"Saya takut atau cemas saat perawatan gigi. Apa yang harus saya lakukan?\",\"a\":\"Rasa takut atau cemas saat ke dokter gigi itu sangat umum, dan Anda tidak sendirian. 💛 Beberapa hal yang bisa membantu: \\n\\n1️⃣ sampaikan rasa cemas Anda kepada bagian pendaftaran saat membuat janji temu\\n2️⃣ ceritakan kepada dokter sebelum pemeriksaan agar tim klinik dapat memahami kebutuhan Anda dan membahasnya saat konsultasi\\n3️⃣ jangan ragu bertanya tentang langkah yang akan dilakukan sampai Anda merasa tenang.\",\"cat\":\"Umum\",\"status\":\"Tampil\",\"ord\":\"9\"}'),
(374, 'features', 'mw922px7', '{\"title\":\"Layanan untuk Seluruh Keluarga\",\"text\":\"Dewasa hingga anak-anak, termasuk perawatan khusus gigi anak.\",\"icon\":\"🐰\",\"img\":\"\",\"ord\":\"5\"}'),
(375, 'features', 'mw923k8k', '{\"title\":\"Jadwal Jelas, Janji Mudah\",\"text\":\"Jadwal dokter bisa dilihat online, buat janji dalam beberapa klik, dan ada asisten AiDA untuk bertanya.\",\"icon\":\"📝\",\"img\":\"\",\"ord\":\"6\"}'),
(58, 'features', 's1', '{\"title\":\"Banyak Spesialis dalam Satu Klinik\",\"icon\":\"🩺\",\"ord\":\"1\",\"text\":\"Dari gigi umum, saraf gigi, kawat gigi, bedah mulut, gigi palsu, gusi, hingga gigi anak, semuanya ditangani dokter spesialis di satu tempat.\",\"img\":\"\"}'),
(59, 'features', 's2', '{\"title\":\"Peralatan Canggih dan Modern\",\"icon\":\"🔬\",\"ord\":\"2\",\"text\":\"Perawatan lebih nyaman dan hasil lebih akurat, dengan tombol “Lihat daftar alat” ke halaman Alat & Teknologi.\",\"img\":\"\"}'),
(60, 'features', 's3', '{\"title\":\"Lingkungan Nyaman dan Bersih\",\"icon\":\"🌿\",\"ord\":3,\"text\":\"Suasana yang nyaman dan penuh kasih sayang akan membuat Anda lebih rileks dalam menerima perawatan.\"}'),
(61, 'features', 's4', '{\"title\":\"Radiologi Lengkap di Tempat\",\"icon\":\"🧪\",\"ord\":\"4\",\"text\":\"Rontgen dental, panoramic, cephalometric, dan CBCT tersedia di klinik, jadi tidak perlu rujukan dan kunjungan jadi lebih singkat.\",\"img\":\"\"}'),
(62, 'history', 's1', '{\"title\":\"2007 – Lanjutan\",\"ord\":\"1\",\"text\":\"Setelah wafatnya drg. Solhah Busro di tahun 2007, perkembangan klinik dibantu dan dikembangkan oleh beliau Dr. drg. Anggraeni Sp.KG. (drg. Rani) yang merupakan salah satu alumnus terbaik Fakultas Kedokteran Gigi Universitas Indonesia.\",\"img\":\"/uploads/321bd0231b3f7fe832d4ca627cbe4489.jpg\",\"imgpos\":\"50% 16%\",\"year\":\"2007\",\"caption\":\"\"}'),
(63, 'history', 's2', '{\"title\":\"1980 – Mulai berdiri\",\"ord\":\"2\",\"text\":\"Pada awalnya, klinik ini merupakan bagian dari rumah pribadi drg. Solhah Busro yang terletak di Jl. Palapa 1 No.4, Pasar Minggu Jakarta Selatan. drg. Solhah Busro merupakan dokter gigi yang juga sekaligus dosen di Fakultas Kedokteran Gigi Universitas Trisakti.\",\"img\":\"/uploads/8e36bd8d49d787aa0c57dcfed34f70a5.png\",\"imgpos\":\"50% 22%\",\"year\":\"1980\",\"caption\":\"\"}'),
