(12, 'settings', 'site', '{\"logoimg\":\"/uploads/98e4ff4ad7f556d40afcfe0f71a6f5f1.jpg\",\"tag\":\"Klinik Gigi Spesialis · Lebih dari 40 Tahun · Pasar Minggu, Jakarta Selatan\",\"a\":\"Empat Dekade\",\"b\":\"Merawat\",\"c\":\"Senyum\",\"d\":\"Sahabat.\",\"sub\":\"Dipercaya lebih dari 40 Tahun dengan dokter gigi spesialis terbaik. Kami menghadirkan perawatan advanced berbasis teknologi digital modern. Dirancang khusus untuk memberikan pengalaman medis yang tepat, presisi, aman, bebas rasa cemas, dan homey bagi seluruh keluarga.\",\"hours\":\"09.00 – 21.00\",\"svTitle\":\"Spesialisasi untuk setiap kebutuhan\",\"svLead\":\"Tujuh bidang perawatan gigi dalam satu klinik.\",\"whyTitle\":\"Mengapa Memilih Dokter Gigi Palapa?\",\"whyText\":\"Palapa Dentists merupakan klinik gigi spesialis di Pasar Minggu, Jakarta Selatan dengan konsep pelayanan klinik gigi profesional dan terpadu bernuansa homey, sehingga berbeda dengan nuansa rumah sakit pada umumnya.\",\"whyImg\":\"/uploads/f0625365f50997582cd1875bb646a773.jpg\",\"whyImgpos\":\"50% 22%\",\"newsTitle\":\"Berita Terbaru\",\"bnSmall\":\"Lingkaran cahaya!!\",\"bnTitle\":\"Kami dari Palapa Dentists\",\"teamImg\":\"/uploads/880b8d2592f430ccb5e2c098a214fb89.jpg\",\"aboutTitle\":\"Tentang Palapa Dentists\",\"about1\":\"Palapa Dentists merupakan klinik gigi spesialis di Jakarta Selatan dengan konsep pelayanan klinik gigi profesional dan terpadu dengan nuansa rumah yang nyaman (homey), sehingga berbeda dengan nuansa rumah sakit pada umumnya.\",\"about2\":\"Sebelumnya, klinik ini dikenal sebagai Praktek Gigi drg. Solhah Busro, M.Kes. Praktek gigi yang bertempat di rumah pribadi drg. Solhah Busro, di Jl. Palapa 1 No. 4, Pasar Minggu Jakarta Selatan ini telah berdiri sejak tahun 1980. drg. Solhah Busro merupakan dokter gigi sekaligus dosen di Fakultas Kedokteran Gigi (FKG) Universitas Trisakti. Beliau wafat pada tahun 2007.\",\"aboutImg\":\"/uploads/130c84123e571c27470e6e5ebb01fe38.jpg\",\"aboutImgpos\":\"50% 50%\",\"featTitle\":\"Layanan Perawatan Gigi Kami meliputi\",\"featLead\":\"Tujuan kami adalah untuk membantu mempertahankan senyum cemerlang Anda dengan tim ahli bedah gigi kami yang berpengalaman. Kami di sini siap untuk membantu menangani kebutuhan gigi Anda.\",\"histTitle\":\"Perjalanan Lebih dari 40 Tahun\",\"histSub\":\"Beberapa titik penting dalam perjalanan Palapa Dentists\",\"insLead\":\"Daftar asuransi yang bekerja sama dengan kami.\",\"insimg\":\"\",\"insNote\":\"Asuransi Anda belum ada di daftar, atau ingin memastikan penjaminan? Tanyakan langsung ke resepsionis kami.\",\"insMsg\":\"Halo Palapa Dentists, saya ingin menanyakan apakah asuransi saya bisa digunakan.\",\"dirLabel\":\"Petunjuk arah\",\"dirUrl\":\"https://www.instagram.com/reel/Dd_VoLVSohV/?psln=am55Y3ZnYzJibHY5\",\"qiscusLabel\":\"Chat via Qiscus\",\"qiscusUrl\":\"https://wa.me/6281281116662?text=Halo%20Admin%2C%20saya%20mau%20tanya\",\"catTitle\":\"Katalog Perawatan\",\"catLead\":\"Daftar perawatan dan layanan di Palapa Dentists. Pilih yang Anda butuhkan, lalu buat janji atau tanyakan ke pendaftaran.\",\"catalogpdf\":\"/uploads/f6f3c98f05f13c94bc8668f273998290.pdf\",\"metaTitle\":\"Palapa Dentists – Klinik Gigi Spesialis Pasar Minggu\",\"metaDesc\":\"Klinik gigi spesialis di Pasar Minggu, Jakarta Selatan: dokter berpengalaman, peralatan modern, suasana nyaman, dan bekerja sama dengan berbagai asuransi.\",\"keyphrase\":\"dokter gigi spesialis pasar minggu\",\"keywords\":\"klinik gigi pasar minggu, dokter gigi jakarta selatan, implan gigi, behel, scaling gigi, dokter gigi anak, palapa dentists\",\"ogimg\":\"/uploads/a52d72c2f625c84c50bc885bab3e9aeb.jpg\",\"mapQ\":\"\",\"mapEmbed\":\"\",\"wd\":\"09:00 - 21:00\",\"we\":\"08:00 - 21:00\",\"addr\":\"Jl. Palapa 1 No.4 Pasar Minggu, Jakarta 12520, Indonesia\",\"phone1\":\"081281116662\",\"phone2\":\"\",\"phone3\":\"\",\"wa1\":\"081116613026\",\"wa2\":\"081281116662\",\"email\":\"reception@palapadentists.com\",\"web\":\"palapadentists.com\",\"wa\":\"6281281116662\",\"fb\":\"\",\"ig\":\"https://www.instagram.com/palapadentists?srtk=bm9qdTNkZTdxMGl0\"}'),
